function toast(message, kind='success') {
  const node = document.createElement('div'); node.className = `toast ${kind}`; node.textContent = message;
  toastRegion.replaceChildren(node); setTimeout(()=>node.remove(), 3600);
}

async function api(path, options={}) {
  const method = options.method || 'GET';
  const headers = { Accept:'application/json', ...(options.body !== undefined ? {'Content-Type':'application/json'} : {}), ...(options.headers||{}) };
  if (!['GET','HEAD'].includes(method) && state.csrf) headers['X-CSRF-Token'] = state.csrf;
  const response = await fetch(`/api/v1${path}`, { method, headers, credentials:'same-origin', body: options.body !== undefined ? JSON.stringify(options.body) : undefined });
  const type = response.headers.get('content-type')||'';
  const data = type.includes('application/json') ? await response.json() : {};
  if (!response.ok) throw new Error(data?.error?.message || `Request failed (${response.status})`);
  if (data.csrfToken) state.csrf = data.csrfToken;
  if (data.user !== undefined) state.user = data.user;
  return data;
}

function routeHref(route='home') { return route === 'home' ? '/' : `/#${route}`; }
function routeLink(route,label,cls='') { return `<a class="${cls}" href="${routeHref(route)}" data-route="${esc(route)}">${label}</a>`; }
function brand() { return `<a class="brand" href="/" data-route="home"><span class="brand-mark"><svg viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M7 21.5 17.5 10 28 21.5 17.5 33 7 21.5Z" fill="currentColor"/><path d="M17 21.5 27.5 10 38 21.5 27.5 33 17 21.5Z" fill="currentColor" opacity=".55"/><circle cx="17.5" cy="21.5" r="2.4" fill="#166534"/></svg></span><span>Mylink</span></a>`; }

