function authPage(kind) {
  const configs = {
    login: ['Welcome back','Sign in to manage your links and review your dashboard.'],
    register: ['Create your account','Start with a clear view of your links and traffic.'],
    forgot: ['Reset your password','We’ll send reset instructions if an active account matches your email.'],
    reset: ['Choose a new password','Use at least 10 characters with upper case, lower case, and a number.'],
    verify: ['Verify your email','Confirm your email to activate your account.'],
  };
  const [title, desc] = configs[kind] || configs.login;
  const token = new URLSearchParams(location.search).get('token')||'';
  let fields = '';
  if (kind==='login') fields=`<div class="field"><label>Email</label><input name="email" type="email" autocomplete="email" required /></div><div class="field"><label>Password</label><input name="password" type="password" autocomplete="current-password" required /></div>`;
  if (kind==='register') fields=`<div class="field"><label>Name</label><input name="displayName" maxlength="80" autocomplete="name" required /></div><div class="field"><label>Email</label><input name="email" type="email" autocomplete="email" required /></div><div class="field"><label>Password</label><input name="password" type="password" autocomplete="new-password" minlength="10" required /><small>At least 10 characters, including upper case, lower case, and a number.</small></div>`;
  if (kind==='forgot') fields=`<div class="field"><label>Email</label><input name="email" type="email" autocomplete="email" required /></div>`;
  if (kind==='reset') fields=`<input name="token" type="hidden" value="${esc(token)}"/><div class="field"><label>New password</label><input name="password" type="password" autocomplete="new-password" minlength="10" required /></div>`;
  if (kind==='verify') fields=`<input name="token" type="hidden" value="${esc(token)}"/><div class="help">${token?'Verification token detected.':'Open the verification link from your email to continue.'}</div>`;
  const action = kind==='login'?'Sign in':kind==='register'?'Create account':kind==='forgot'?'Send reset link':kind==='reset'?'Update password':'Verify email';
  return `${siteNav()}<main class="auth-layout"><section class="auth-card"><h1>${esc(title)}</h1><p>${esc(desc)}</p><div id="form-message" class="form-message" role="status"></div><form class="form" id="auth-form" data-kind="${kind}">${fields}<button class="btn btn-primary" type="submit">${action}</button></form><div class="auth-alt">${kind==='login'?`New here? ${routeLink('register','Create an account')}`:kind==='register'?`Already have an account? ${routeLink('login','Sign in')}`:kind==='forgot'?routeLink('login','Back to sign in'):kind==='reset'?routeLink('forgot','Request another reset link'):routeLink('login','Continue to sign in')}</div></section></main>${footer()}`;
}

function bindAuth() {
  const form = document.querySelector('#auth-form'); if(!form)return;
  form.addEventListener('submit',async e=>{
    e.preventDefault(); const data=Object.fromEntries(new FormData(form).entries()); const msg=document.querySelector('#form-message'); const button=form.querySelector('button[type=submit]'); button.disabled=true; msg.className='form-message';
    try{
      const kind=form.dataset.kind;
      const path={login:'/auth/login',register:'/auth/register',forgot:'/auth/forgot-password',reset:'/auth/reset-password',verify:'/auth/verify-email'}[kind];
      const result=await api(path,{method:'POST',body:data});
      msg.textContent=result.message||'Done.'; msg.className='form-message success show';
      if(kind==='login'){
        const pending=localStorage.getItem('pendingUrl');
        if(pending){localStorage.removeItem('pendingUrl'); location.hash='create';}
        else location.hash=state.user?.role==='admin'||state.user?.role==='super_admin'?'admin':'app';
        renderRoute();
      } else if(kind==='verify') setTimeout(()=>{location.hash='login';renderRoute()},1400);
      else if(kind==='reset') setTimeout(()=>{location.hash='login';renderRoute()},1200);
    }catch(error){msg.textContent=error.message;msg.className='form-message error show';}
    finally{button.disabled=false;}
  });
}

