const routeTitles = Object.fromEntries([...userMenu,...adminMenu].map(([route,label])=>[route,label]));
routeTitles['admin-links']='Users creations';
routeTitles.notifications='Notifications';
const payoutMethods=[
  {name:'USDT',mark:'₮',className:'usdt',hint:'Crypto wallet · choose a network'},
  {name:'UPI',mark:'UPI',className:'upi',hint:'Indian UPI ID'},
  {name:'PayPal',mark:'P',className:'paypal',hint:'PayPal account email'},
  {name:'Binance',mark:'◆',className:'binance',hint:'Binance Pay ID or wallet'},
  {name:'Bank transfer',mark:'bank',className:'bank',hint:'Account and bank details'},
];
function payoutMark(method){const item=payoutMethods.find(x=>x.name===method);return item?`<span class="payment-logo ${item.className}">${item.mark==='bank'?icon('bank'):esc(item.mark)}</span>`:'';}
function payoutFields(method){
  if(method==='Bank transfer')return `<div class="field-row payout-fields-row"><div class="field"><label for="payout-account-name">Account holder name</label><input id="payout-account-name" name="payoutAccountName" maxlength="60" autocomplete="name" placeholder="Name on bank account" required /></div><div class="field"><label for="payout-account-number">Account number</label><input id="payout-account-number" name="payoutAccountNumber" maxlength="50" inputmode="numeric" autocomplete="off" placeholder="Bank account number" required /></div><div class="field"><label for="payout-ifsc">IFSC code</label><input id="payout-ifsc" name="payoutIfsc" maxlength="15" autocapitalize="characters" autocomplete="off" placeholder="e.g. ABCD0123456" required /></div><div class="field"><label for="payout-bank-name">Bank name</label><input id="payout-bank-name" name="payoutBankName" maxlength="60" autocomplete="off" placeholder="Name of your bank" required /></div></div>`;
  if(method==='USDT')return `<div class="field-row payout-fields-row usdt-fields-row"><div class="field"><label>Chain / network</label><div class="payout-chain-dropdown"><input type="hidden" id="payout-chain" name="payoutChain" value=""/><button type="button" class="payout-chain-trigger" data-action="toggle-usdt-chain" aria-expanded="false"><span class="payout-chain-value">Select a chain</span><span class="payout-select-caret">${icon('arrow')}</span></button><div class="payout-chain-menu" hidden><button type="button" data-action="choose-usdt-chain" data-chain="TRC20"><b>TRC20</b><small>Tron network</small></button><button type="button" data-action="choose-usdt-chain" data-chain="ERC20"><b>ERC20</b><small>Ethereum network</small></button><button type="button" data-action="choose-usdt-chain" data-chain="BEP20"><b>BEP20</b><small>BNB Smart Chain</small></button></div></div></div><div class="field"><label for="payout-wallet">USDT wallet address</label><input id="payout-wallet" name="payoutWallet" minlength="5" maxlength="180" autocomplete="off" placeholder="Paste receiving wallet address" required /></div></div>`;
  const fields={UPI:['UPI ID','name@bank'],PayPal:['PayPal account email','you@example.com'],Binance:['Binance Pay ID or wallet','Enter your Binance receiving details']};const [label,placeholder]=fields[method]||['Payment account details','Enter your receiving details'];
  return `<div class="field payout-single-field"><label for="payout-value">${label}</label><input id="payout-value" name="payoutValue" minlength="5" maxlength="230" autocomplete="off" placeholder="${placeholder}" required /></div>`;
}

function sidebar(active) {
  const admin=state.user&&['admin','super_admin'].includes(state.user.role);
  const menu=admin?adminMenu:userMenu;
  return `<aside class="sidebar" id="sidebar"><div class="sidebar-brand">${brand()}</div><div class="side-label">${admin?'Administration':'Publisher'}</div><nav class="side-nav" aria-label="Dashboard navigation">${menu.map(([route,label,iconName])=>`<a class="side-link ${route===active?'active':''}" href="${routeHref(route)}" data-route="${route}"><span class="ico">${icon(iconName)}</span>${esc(label)}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="user-mini">${avatarMarkup(state.user)}<span class="user-mini-copy"><b>${esc(state.user?.displayName||state.user?.email)}</b><small>${esc(state.user?.role==='user'?'Member':'Administrator')}</small></span><button class="sidebar-logout" type="button" data-action="logout" aria-label="Logout"><span class="ico">${icon('signOut')}</span><span>Logout</span></button></div><button class="side-link sidebar-logout-desktop" style="width:100%;border:0;background:transparent" data-action="logout"><span class="ico">${icon('signOut')}</span>Sign out</button></div></aside>`;
}

function appShell(active, content) {
  const title=routeTitles[active]||'Dashboard';
  const admin=state.user&&['admin','super_admin'].includes(state.user.role);
  const unread=Number(state.notificationsUnread||0);
  return `<div class="app-shell ${admin?'admin-shell':'user-shell'}">${sidebar(active)}<div class="main-area"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" aria-label="Open navigation" data-action="sidebar-open">${icon('menu')}</button><div><div class="crumb">${admin?'Administration':'Publisher'}</div><h1>${esc(title)}</h1></div></div><div class="top-actions"><button class="icon-btn notification-btn" aria-label="Notifications${unread?`, ${unread} unread`:''}" data-route="notifications">${icon('bellDot')}${unread?`<span class="notification-count-badge" aria-hidden="true">${unread>99?'99+':unread}</span>`:''}</button>${avatarMarkup(state.user,'avatar profile-label')}</div></header><main class="page-content">${content}</main></div></div>`;
}

function metricCard(label,value,icon,note='',variant='') { return `<article class="metric-card ${esc(variant)}"><div class="metric-top"><span>${esc(label)}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-note">${esc(note)}</div></article>`; }

function chartBars(days, key='visits', label='Visits') {
  const source=days?.slice(-12)||[]; if(!source.length)return `<div class="empty-state">Analytics will appear here when visitors open your links.</div>`;
  const max=Math.max(1,...source.map(x=>Number(x[key]||0)));
  return `<div class="chart" role="img" aria-label="${esc(label)} by day">${source.map((x,i)=>`<div class="bar-col"><div class="bar ${Number(x[key])>0?'strong':''}" style="height:${Math.max(2,Number(x[key]||0)/max*100)}%" title="${esc(x.day)}: ${Number(x[key]||0)}"></div><span class="bar-label">${esc(new Date(x.day+'T00:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'}))}</span></div>`).join('')}</div><div class="chart-legend"><span><i class="legend-dot green"></i>${esc(label)}</span><span><i class="legend-dot"></i>Unlock completions are tracked separately</span></div>`;
}

function overviewTrafficWindow(days,count=14){
  const byDay=new Map((days||[]).map(item=>[String(item.day),item]));const now=new Date();const today=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()));
  return Array.from({length:count},(_,index)=>{const date=new Date(today);date.setUTCDate(today.getUTCDate()-(count-index-1));const day=date.toISOString().slice(0,10);const item=byDay.get(day)||{};return{day,visits:Number(item.visits||0)};});
}
function overviewTrafficMarkup(series,chartId='overview-traffic-chart'){const total=series.reduce((sum,item)=>sum+item.visits,0);return `<div class="overview-traffic-chart-wrap"><canvas id="${esc(chartId)}" data-series="${esc(encodeURIComponent(JSON.stringify(series)))}" role="img" aria-label="Daily link visits for the last 14 days"></canvas>${total? '':'<div class="overview-chart-empty">No visits recorded in this period yet.</div>'}</div><div class="overview-chart-footer"><span><i class="overview-chart-dot"></i>Daily visits</span><span>Last 14 days · ${total.toLocaleString()} total</span></div>`;}
let overviewTrafficChartInstance=null;
function drawTrafficChart(canvasId='overview-traffic-chart'){
  const canvas=document.getElementById(canvasId);if(!canvas||!window.Chart)return;
  let series=[];try{series=JSON.parse(decodeURIComponent(canvas.dataset.series||'%5B%5D'));}catch{}
  const labels=series.map(item=>new Date(`${item.day}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'}));const context=canvas.getContext('2d');const fill=context.createLinearGradient(0,0,0,230);fill.addColorStop(0,'rgba(22,163,74,.22)');fill.addColorStop(1,'rgba(22,163,74,0)');
  overviewTrafficChartInstance=new window.Chart(context,{type:'line',data:{labels,datasets:[{label:'Visits',data:series.map(item=>item.visits),borderColor:'#15803d',backgroundColor:fill,borderWidth:2.5,fill:true,tension:.38,pointRadius:0,pointHoverRadius:4,pointHoverBackgroundColor:'#15803d',pointHoverBorderColor:'#fff',pointHoverBorderWidth:2}]},options:{responsive:true,maintainAspectRatio:false,normalized:true,interaction:{intersect:false,mode:'index'},plugins:{legend:{display:false},tooltip:{displayColors:false,backgroundColor:'#10251a',titleColor:'#dcfce7',bodyColor:'#fff',padding:10,cornerRadius:9,callbacks:{label:context=>`Visits: ${Number(context.parsed.y||0).toLocaleString()}`}}},scales:{x:{grid:{display:false},border:{display:false},ticks:{color:'#8a9a91',font:{size:10},maxTicksLimit:7,maxRotation:0,autoSkip:true}},y:{beginAtZero:true,border:{display:false},grid:{color:'rgba(148,163,184,.16)',drawTicks:false},ticks:{color:'#8a9a91',font:{size:10},precision:0,maxTicksLimit:5,padding:8}}}}});
}
function drawOverviewTrafficChart(){drawTrafficChart('overview-traffic-chart');}

function performingCreationsMarkup(items){
  if(!items?.length)return emptyTable('Your creations will appear here as soon as you publish or share them.',`<a class="btn btn-outline btn-small" href="/#links" data-route="links">Manage creations</a>`);
  const kinds={link:{label:'Link',icon:'link'},file:{label:'File',icon:'file'},post:{label:'Post',icon:'file'},tree:{label:'Tree',icon:'link'}};
  const normalized=items.slice(0,5).map(item=>{const type=kinds[item.type]?item.type:'link';return{...item,type,...kinds[type],url:location.origin+item.path,visits:Number(item.visits||0)};});
  const desktop=normalized.map(item=>`<tr><td><div class="overview-creation-title"><span class="overview-creation-icon type-${item.type}">${icon(item.icon)}</span><span><strong>${esc(item.title)}</strong><small>${esc(item.path)}</small></span></div></td><td><span class="overview-creation-type type-${item.type}">${esc(item.label)}</span></td><td><strong class="overview-creation-visits">${item.visits.toLocaleString()}</strong></td><td>${dateFmt(item.createdAt)}</td><td><a class="overview-creation-open" href="${esc(item.url)}" target="_blank" rel="noopener">Open ${icon('arrow')}</a></td></tr>`).join('');
  const mobile=normalized.map(item=>`<a class="overview-performing-card" href="${esc(item.url)}" target="_blank" rel="noopener"><div class="overview-performing-main"><span class="overview-creation-icon type-${item.type}">${icon(item.icon)}</span><span class="overview-performing-copy"><strong>${esc(item.title)}</strong><small><span class="overview-creation-type type-${item.type}">${esc(item.label)}</span><span class="overview-performing-path">${esc(item.path)}</span></small></span><span class="overview-performing-count"><b>${item.visits.toLocaleString()}</b><small>visits</small></span></div><div class="overview-performing-foot"><span>Created ${dateFmt(item.createdAt)}</span><span>Open ${icon('arrow')}</span></div></a>`).join('');
  return `<div class="table-wrap overview-performing-desktop"><table class="data-table overview-performing-table"><thead><tr><th>Creation</th><th>Type</th><th>Visits</th><th>Created</th><th></th></tr></thead><tbody>${desktop}</tbody></table></div><div class="overview-performing-mobile">${mobile}</div>`;
}

function emptyTable(message,button) { return `<div class="empty-state"><b>${esc(message)}</b>${button||''}</div>`; }

async function userDashboard() {
  const data=await api('/analytics/overview');const traffic=overviewTrafficWindow(data.daily);
  return `<div class="welcome-row overview-welcome"><div><h2>Welcome back, ${esc(state.user.displayName.split(' ')[0])}</h2><p>A clear snapshot of your links, traffic, and earnings.</p></div></div>
    <section class="metric-grid overview-metrics">${metricCard('Links',Number(data.creationCounts?.links||0).toLocaleString(),icon('link'),'Short links you created')}${metricCard('Files',Number(data.creationCounts?.files||0).toLocaleString(),icon('file'),'File links shared')}${metricCard('Trees',Number(data.creationCounts?.trees||0).toLocaleString(),icon('tree'),'Published link trees')}${metricCard('Posts',Number(data.creationCounts?.posts||0).toLocaleString(),icon('file'),'Articles created')}${metricCard('Raw visits',Number(data.totals.rawVisits).toLocaleString(),icon('eye'),'Recorded short-link visits')}${metricCard('Destination clicks',Number(data.totals.redirects).toLocaleString(),icon('arrow'),'Successfully sent to destinations')}${metricCard('Withdrawable',money(data.earnings.withdrawablePaise),icon('wallet'),'After pending reservations','overview-wallet-card')}</section>
    <div class="content-grid overview-content-grid"><section class="panel overview-panel"><div class="panel-header"><div><h3>Traffic activity</h3><p>Daily visits across all your short links</p></div><a class="link-button" href="/#analytics" data-route="analytics">Full analytics ${icon('arrow')}</a></div>${overviewTrafficMarkup(traffic)}</section><section class="panel overview-panel overview-earnings-panel"><div class="panel-header"><div><h3>Earnings summary</h3><p>Amounts update as records are reviewed</p></div><a class="icon-btn overview-view-button" href="/#earnings" data-route="earnings" aria-label="View earnings">${icon('arrow')}</a></div><div class="overview-earning-grid"><div class="overview-earning-item overview-earning-today"><div class="overview-earning-label">${icon('clock')}<span>Today</span></div><strong>${money(data.earnings.todayPaise)}</strong><small>Pending estimate</small></div><div class="overview-earning-item overview-earning-month"><div class="overview-earning-label">${icon('chart')}<span>This month</span></div><strong>${money(data.earnings.monthPaise)}</strong><small>Recorded earnings</small></div><div class="overview-earning-item overview-earning-approved"><div class="overview-earning-label">${icon('seal')}<span>Approved</span></div><strong>${money(data.earnings.approvedPaise)}</strong><small>Ready for payout rules</small></div><div class="overview-earning-item overview-earning-pending"><div class="overview-earning-label">${icon('wallet')}<span>Pending</span></div><strong>${money(data.earnings.pendingPaise)}</strong><small>Awaiting review</small></div></div><div class="notice warning overview-earning-note">${icon('shield')}<span>Visits and completed unlocks are not payable without provider verification.</span></div></section></div>
    <section class="panel overview-recent-panel overview-performing-panel"><div class="panel-header"><div><h3>Performing creations</h3><p>Links, files, posts and trees ranked by visits</p></div><a class="link-button" href="/#links" data-route="links">Manage creations ${icon('arrow')}</a></div>${performingCreationsMarkup(data.performingCreations)}</section>`;
}

function linksTable(items, admin=false) {
  if(!items.length)return emptyTable('No links match this view.');
  const rows=items.map(item=>{
    const shortUrl=location.origin+'/s/'+item.code;
    const destination=String(item.destination_url||'');
    let destinationHost='';try{destinationHost=new URL(destination).hostname;}catch{}
    return {item,shortUrl,destinationHost};
  });
  const table=`<div class="table-wrap desktop-links-table"><table class="data-table"><thead><tr>${admin?'<th>Owner</th>':''}<th>Link</th><th>Destination</th><th>Short URL</th><th>Visits</th>${admin?'':'<th>Eligible</th><th>Earnings</th>'}<th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody>${rows.map(({item,shortUrl,destinationHost})=>`<tr>${admin?`<td>${esc(item.owner_email)}</td>`:''}<td><strong>${esc(item.title||'Untitled link')}</strong><br><span class="muted mono">/${esc(item.code)}</span></td><td><a class="destination-link" href="${esc(item.destination_url||'#')}" target="_blank" rel="noopener noreferrer" title="${esc(item.destination_url||'')}">${esc(destinationHost||item.destination_url||'—')}</a></td><td><a class="text-link mono" href="/s/${encodeURIComponent(item.code)}" target="_blank" rel="noopener noreferrer">${esc(shortUrl)}</a></td><td>${Number(item.raw_visits??item.visits??0).toLocaleString()}</td>${admin?'':`<td>${Number(item.eligible_clicks||0).toLocaleString()}</td><td>${money(item.earnings_paise)}</td>`}<td>${statusPill(item.status)}</td><td>${dateFmt(item.created_at)}</td><td><div class="link-actions"><button class="btn btn-outline btn-small" data-action="copy-link" data-url="${esc(shortUrl)}">Copy</button>${admin?`<button class="btn btn-outline btn-small" data-action="admin-link-status" data-id="${esc(item.id)}" data-status="${esc(item.status)}">Review</button>`:`<button class="btn btn-outline btn-small" data-action="toggle-link" data-id="${esc(item.id)}" data-status="${esc(item.status)}">${item.status==='active'?'Pause':'Enable'}</button><button class="btn btn-outline btn-small" data-action="edit-link" data-id="${esc(item.id)}" aria-label="Edit ${esc(item.title||item.code)}">${icon('pencil')} Edit</button><button class="btn btn-outline btn-small" data-action="link-analytics" data-id="${esc(item.id)}">Stats</button>`}</div></td></tr>`).join('')}</tbody></table></div>`;
  if(admin)return table;
  const cards=`<div class="mobile-link-list">${rows.map(({item,shortUrl,destinationHost})=>`<article class="mobile-link-card"><div class="mobile-link-head"><div class="mobile-link-title"><span class="mobile-link-icon">${icon('link')}</span><div><h3>${esc(item.title||'Untitled link')}</h3><span class="mono muted">/${esc(item.code)}</span></div></div>${statusPill(item.status)}</div><div class="mobile-link-destination"><span>Destination</span><a href="${esc(item.destination_url||'#')}" target="_blank" rel="noopener noreferrer">${esc(destinationHost||item.destination_url||'—')} ↗</a></div><div class="mobile-link-url"><span>Short URL</span><a class="mono" href="/s/${encodeURIComponent(item.code)}" target="_blank" rel="noopener noreferrer">${esc(shortUrl)}</a></div><div class="mobile-link-metrics"><div><span>Visits</span><strong>${Number(item.raw_visits||0).toLocaleString()}</strong></div><div><span>Earnings</span><strong>${money(item.earnings_paise)}</strong></div><div><span>CPM</span><strong>${money(Number(item.raw_visits)?Number(item.earnings_paise||0)*1000/Number(item.raw_visits):0)}</strong></div></div><div class="mobile-link-foot"><span>Created ${dateFmt(item.created_at)}</span><div class="mobile-link-actions"><button class="btn btn-primary btn-small" data-action="copy-link" data-url="${esc(shortUrl)}">Copy link</button><button class="btn btn-outline btn-small" data-action="toggle-link" data-id="${esc(item.id)}" data-status="${esc(item.status)}">${item.status==='active'?'Pause':'Enable'}</button><button class="icon-btn" aria-label="Link analytics" data-action="link-analytics" data-id="${esc(item.id)}">${icon('chart')}</button><button class="icon-btn" aria-label="Edit link" data-action="edit-link" data-id="${esc(item.id)}">${icon('pencil')}</button></div></div></article>`).join('')}</div>`;
  return table+cards;
}

async function createLinkPage() {
  return `<div class="welcome-row"><div><h2>Create a short link</h2><p>Only HTTP and HTTPS destinations are allowed.</p></div></div><div class="content-grid"><section class="panel"><form class="form" id="create-link-form"><div class="field"><label for="destinationUrl">Destination URL</label><input id="destinationUrl" name="destinationUrl" type="url" placeholder="https://example.com/page" required /></div><div class="field-row"><div class="field"><label>Custom alias <span class="muted">(optional)</span></label><input name="alias" pattern="[A-Za-z0-9_-]{3,32}" placeholder="summer-campaign" /></div><div class="field"><label>Link title</label><input name="title" maxlength="120" placeholder="Summer launch" /></div></div><div class="field-row"><div class="field"><label>Campaign</label><input name="campaign" maxlength="100" placeholder="Summer 2026" /></div><div class="field"><label>Description <span class="muted">(optional)</span></label><input name="description" maxlength="500" placeholder="Internal note" /></div></div><div class="file-link-toggle-list link-security-options"><label class="file-link-toggle-row"><span class="file-link-toggle-icon">${icon('clock')}</span><span class="file-link-toggle-copy"><b>Set expiry</b><small>Automatically stop this link at a chosen date and time.</small></span><input type="checkbox" name="expiryEnabled" data-reveal="short-expiry-field" /><span class="file-link-switch" aria-hidden="true"></span></label><div class="field file-link-reveal" id="short-expiry-field" hidden><label for="short-expires-at">Expiry date and time</label><input id="short-expires-at" name="expiresAt" type="datetime-local" disabled /><small>Choose a future date and time.</small></div><label class="file-link-toggle-row"><span class="file-link-toggle-icon">${icon('lock')}</span><span class="file-link-toggle-copy"><b>Password protection</b><small>Ask visitors for a password before continuing.</small></span><input type="checkbox" name="passwordEnabled" data-reveal="short-password-field" /><span class="file-link-switch" aria-hidden="true"></span></label><div class="field file-link-reveal" id="short-password-field" hidden><label for="short-link-password">Link password</label><input id="short-link-password" name="password" type="password" minlength="6" maxlength="6" autocomplete="new-password" placeholder="Exactly 6 characters" disabled /><small>Password must be exactly 6 characters.</small></div><label class="file-link-toggle-row"><span class="file-link-toggle-icon">${icon('eye')}</span><span class="file-link-toggle-copy"><b>Limit views per IP</b><small>Set how many visits one IP address can make.</small></span><input type="checkbox" name="perIpEnabled" data-reveal="short-ip-field" /><span class="file-link-switch" aria-hidden="true"></span></label><div class="field file-link-reveal" id="short-ip-field" hidden><label for="short-ip-limit">Views per IP</label><input id="short-ip-limit" name="perIpLimit" type="number" min="1" max="10000000" placeholder="e.g. 5" disabled /><small>Enter a positive whole number.</small></div></div><button class="btn btn-primary" type="submit">Create short link</button></form><div id="created-link-result"></div></section><aside class="panel"><h3 style="margin-top:0">Before you share</h3><p class="help">The destination remains server-side until visitors finish the configured unlock flow. A completed flow is tracked separately from provider-verified eligibility.</p><div class="notice" style="margin-top:14px">Configured ad partners must permit the format you use. A step click does not count as a verified impression or conversion.</div></aside></div>`;
}

async function createFileLinkPage() {
  const telegram=await api('/profile/telegram/bots');const bots=telegram.items||[];
  return `<div class="welcome-row file-link-welcome"><div><h2>Create file link</h2><p>Share files through your Telegram storage bot and manage the link in one place.</p></div></div><div class="content-grid file-link-layout"><section class="panel file-link-form-panel"><div class="file-link-form-heading"><span class="file-link-heading-icon">${icon('file')}</span><div><h3>File link details</h3><p>Set up your file destination and sharing options.</p></div></div><form class="form file-link-form" id="create-file-link-form"><div class="field"><label for="file-link-url">File URL</label><input id="file-link-url" name="destinationUrl" type="url" placeholder="https://example.com/your-file" required /><small>Paste a direct file link or a Telegram storage link.</small></div><div class="field-row"><div class="field"><label for="file-link-title">File name / title</label><input id="file-link-title" name="title" maxlength="120" placeholder="My shared file" required /></div><div class="field"><label for="file-link-alias">Custom alias <span class="muted">(optional)</span></label><input id="file-link-alias" name="alias" pattern="[A-Za-z0-9_-]{3,32}" placeholder="my-file" /></div></div><div class="field"><label for="file-link-bot">Select bot</label><select id="file-link-bot" name="bot" ${bots.length?'required':''}><option value="">Choose a Telegram bot</option>${bots.map(bot=>`<option value="${esc(bot.id)}">${esc(bot.botName)} · ${esc(bot.botId)}</option>`).join('')}</select><small>${bots.length?`${bots.length} Telegram bot${bots.length===1?' is':'s are'} available.`:'No bots added yet. Add one in Security settings.'} ${bots.length?'':'<a href="/#security" data-route="security">Open Security settings</a>'}</small></div><div class="file-link-toggle-list"><label class="file-link-toggle-row"><span class="file-link-toggle-icon">${icon('clock')}</span><span class="file-link-toggle-copy"><b>Set expiry</b><small>Automatically stop this link at a chosen date and time.</small></span><input type="checkbox" name="expiryEnabled" data-reveal="file-expiry-field" /><span class="file-link-switch" aria-hidden="true"></span></label><div class="field file-link-reveal" id="file-expiry-field" hidden><label for="file-link-expiry">Expiry date and time</label><input id="file-link-expiry" name="expiresAt" type="datetime-local" disabled /><small>Choose a future date and time.</small></div><label class="file-link-toggle-row"><span class="file-link-toggle-icon">${icon('lock')}</span><span class="file-link-toggle-copy"><b>Password protection</b><small>Require a password before visitors can continue.</small></span><input type="checkbox" name="passwordEnabled" data-reveal="file-password-field" /><span class="file-link-switch" aria-hidden="true"></span></label><div class="field file-link-reveal" id="file-password-field" hidden><label for="file-link-password">Link password</label><input id="file-link-password" name="password" type="password" minlength="6" maxlength="6" autocomplete="new-password" placeholder="Exactly 6 characters" disabled /><small>Password must be exactly 6 characters.</small></div><label class="file-link-toggle-row"><span class="file-link-toggle-icon">${icon('eye')}</span><span class="file-link-toggle-copy"><b>Limit views per IP</b><small>Set the maximum visits allowed from one IP address.</small></span><input type="checkbox" name="perIpEnabled" data-reveal="file-ip-field" /><span class="file-link-switch" aria-hidden="true"></span></label><div class="field file-link-reveal" id="file-ip-field" hidden><label for="file-link-ip-limit">Views per IP</label><input id="file-link-ip-limit" name="maxVisits" type="number" min="1" max="10000000" placeholder="e.g. 5" disabled /><small>Set a positive whole number.</small></div><label class="file-link-toggle-row"><span class="file-link-toggle-icon">${icon('megaphone')}</span><span class="file-link-toggle-copy"><b>Bot ads</b><small>Show ads in the bot flow to support earnings.</small></span><input type="checkbox" name="botAdsEnabled" /><span class="file-link-switch" aria-hidden="true"></span></label><label class="file-link-toggle-row"><span class="file-link-toggle-icon">${icon('link')}</span><span class="file-link-toggle-copy"><b>Convert to short link</b><small>Create a trackable Mylink URL for this file.</small></span><input type="checkbox" name="convertToShortLink" checked /><span class="file-link-switch" aria-hidden="true"></span></label></div><p class="file-link-income-note">Boost your income with Telegram storage channel file links.</p><button class="btn btn-primary file-link-submit" type="submit">Create file link <span aria-hidden="true">→</span></button></form><div id="created-file-link-result"></div></section><aside class="panel file-link-guide"><span class="file-link-guide-icon">${icon('support')}</span><h3>Before you share</h3><p>Choose your bot, add the file URL, and decide whether to create a Mylink short URL.</p><div class="file-link-guide-note">Telegram file delivery and bot ads require a connected bot service. A saved bot token alone does not activate delivery.</div></aside></div>`;
}

function postAccessSettingsMarkup(existing){const hasPassword=Boolean(existing?.has_password);const adsEnabled=Boolean(existing?.ads_enabled);return `<div class="file-link-toggle-list post-access-controls"><label class="file-link-toggle-row"><span class="file-link-toggle-icon">${icon('lock')}</span><span class="file-link-toggle-copy"><b>Protect this post</b><small>Require a 6-digit password before visitors can read the article.</small></span><input type="checkbox" name="postPasswordEnabled" data-reveal="post-access-password-field" data-optional="${hasPassword?'true':'false'}" ${hasPassword?'checked':''} /><span class="file-link-switch" aria-hidden="true"></span></label><div class="field file-link-reveal" id="post-access-password-field" ${hasPassword?'':'hidden'}><label>6-digit post password</label><input name="postPassword" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="new-password" placeholder="${hasPassword?'Enter a new code or leave blank to keep current':'Enter 6 digits'}" ${hasPassword?'':'disabled'} /><small>${hasPassword?'Leave blank to keep the current password.':'Choose exactly 6 digits.'}</small></div><label class="file-link-toggle-row post-banner-ads-toggle"><span class="file-link-toggle-icon">${icon('megaphone')}</span><span class="file-link-toggle-copy"><b>Banner ads on public post</b><small>Show the shared 10-second banner popup on this post.</small></span><input type="checkbox" name="adsEnabled" ${adsEnabled?'checked':''} /><span class="file-link-switch" aria-hidden="true"></span></label></div>`;}
async function createPostPage(){const editId=new URLSearchParams(location.search).get('edit')||'';const existing=editId?(await api(`/profile/posts/${encodeURIComponent(editId)}`)).article:null;const val=(x)=>esc(x||'');return `<div class="welcome-row"><div><h2>${existing?'Edit post':'Create post'}</h2><p>Write and publish an article with headings, images, lists, quotes, and tables.</p></div></div><section class="panel post-editor-panel"><form id="article-form" data-article-id="${val(existing?.id)}" data-has-password="${existing?.has_password?'true':'false'}" class="form"><div class="field-row"><div class="field"><label>Article title</label><input name="title" maxlength="160" value="${val(existing?.title)}" placeholder="Give your article a clear title" required /></div><div class="field"><label>Post slug</label><div class="tree-slug-field"><span>${esc(location.host)}/post/</span><input name="slug" maxlength="80" pattern="[a-z0-9][a-z0-9-]{1,78}[a-z0-9]" value="${val(existing?.slug)}" placeholder="my-first-post" required /></div></div></div><div class="field"><label>Short introduction</label><textarea name="excerpt" rows="2" maxlength="500" placeholder="A short summary for readers and sharing">${val(existing?.excerpt)}</textarea></div><div class="field"><label>Cover image URL <span class="muted">(optional)</span></label><input name="coverImage" type="url" value="${val(existing?.cover_image)}" placeholder="https://example.com/cover.jpg" /></div>${existing?'':`<div class="file-link-toggle-list post-link-controls"><label class="file-link-toggle-row"><span class="file-link-toggle-icon">${icon('link')}</span><span class="file-link-toggle-copy"><b>Convert to short link</b><small>Create a trackable Mylink URL for this article.</small></span><input type="checkbox" name="convertToShortLink" checked /><span class="file-link-switch" aria-hidden="true"></span></label></div>`}${postAccessSettingsMarkup(existing)}<div class="field"><label>Article body</label><div id="article-toolbar"><span class="ql-formats"><select class="ql-header"><option selected></option><option value="1"></option><option value="2"></option><option value="3"></option></select><select class="ql-size"><option value="small"></option><option selected></option><option value="large"></option><option value="huge"></option></select></span><span class="ql-formats"><button class="ql-bold"></button><button class="ql-italic"></button><button class="ql-underline"></button><button class="ql-strike"></button><button class="ql-script" value="sub" title="Subscript">xₙ</button><button class="ql-script" value="super" title="Superscript">xⁿ</button></span><span class="ql-formats"><button class="ql-list" value="ordered"></button><button class="ql-list" value="bullet"></button><button class="ql-blockquote"></button><button class="ql-align" value=""></button><button class="ql-align" value="center"></button></span><span class="ql-formats"><button class="ql-link"></button><button class="ql-image"></button><button type="button" class="article-insert-table" data-action="article-insert-table" title="Insert table" aria-label="Insert table">▦</button></span><span class="ql-formats"><button class="ql-clean"></button></span></div><div id="article-content" class="article-content"></div><input type="hidden" name="contentHtml" /></div><div class="post-publish-row"><span class="muted">${existing?'Save changes to update your article.':'Publishing creates a public page at /post/your-slug'}</span><button class="btn btn-primary" type="submit">${existing?'Save article':'Publish article'}</button></div></form></section><div id="article-result"></div>`}
function publicPostHeaderMarkup(){return `<div class="post-desktop-nav">${siteNav()}</div><header class="public-post-header"><div class="public-post-brand">${brand()}<span class="public-post-kind">Post</span></div>${registerCtaMarkup('post-register-cta')}</header>`;}
function publicAuthorSocialUrl(key,value){const raw=String(value||'').trim();if(!raw)return '';let candidate=raw;if(!/^https?:\/\//i.test(candidate)){const handle=candidate.replace(/^@/,'').replace(/^https?:\/\//i,'').replace(/^www\./i,'');const paths={telegram:`https://t.me/${handle}`,whatsapp:`https://wa.me/${handle.replace(/\D/g,'')}`,youtube:`https://youtube.com/@${handle}`,facebook:`https://facebook.com/${handle}`,instagram:`https://instagram.com/${handle}`,snapchat:`https://snapchat.com/add/${handle}`,tiktok:`https://tiktok.com/@${handle}`,x:`https://x.com/${handle}`,website:`https://${handle}`};candidate=paths[key]||'';}try{const url=new URL(candidate);return ['https:','http:'].includes(url.protocol)?url.href:'';}catch{return '';}}
function publicPostAuthorMarkup(author={}){const links=[['telegram','Telegram','telegram-logo'],['whatsapp','WhatsApp','whatsapp-logo'],['youtube','YouTube','youtube-logo'],['facebook','Facebook','facebook-logo'],['instagram','Instagram','instagram-logo'],['snapchat','Snapchat','snapchat-logo'],['tiktok','TikTok','tiktok-logo'],['x','X / Twitter','twitter-logo'],['website','Website','globe']].map(([key,label,iconName])=>({key,label,iconName,url:publicAuthorSocialUrl(key,author.socialLinks?.[key])}));const name=author.displayName||'Mylink creator';const avatar=author.avatarUrl?`<img src="${esc(author.avatarUrl)}" alt="${esc(name)}" loading="lazy"/>`:`<span>${esc(name.trim().slice(0,1).toUpperCase()||'M')}</span>`;return `<section class="post-author-card" aria-label="About the author"><div class="post-author-avatar">${avatar}</div><div class="post-author-content"><h2>${esc(name)}</h2><div class="post-author-follow-row"><span class="post-author-follow-label">Follow us on</span><nav class="post-author-socials" aria-label="Author social profiles">${links.map(link=>link.url?`<a href="${esc(link.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(link.label)}" title="${esc(link.label)}"><i class="ph-duotone ph-${link.iconName} ph-icon" aria-hidden="true"></i></a>`:`<span class="is-unlinked" aria-label="${esc(link.label)} link not provided" title="${esc(link.label)} link not provided"><i class="ph-duotone ph-${link.iconName} ph-icon" aria-hidden="true"></i></span>`).join('')}</nav></div></div></section>`;}
function publicArticleMarkup(a){return `<main class="public-article" style="background:#fff;padding:0"><article style="width:100%;max-width:820px;margin:0 auto;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none"><span class="eyebrow">ARTICLE</span><h1>${esc(a.title)}</h1>${a.excerpt?`<p class="article-excerpt">${esc(a.excerpt)}</p>`:''}<div class="article-meta">Published ${dateTimeFmt(a.created_at)} · ${Number(a.viewCount).toLocaleString()} views</div>${a.cover_image?`<img class="article-cover" src="${esc(a.cover_image)}" alt=""/>`:''}<div class="article-body">${a.content_html}</div>${publicPostAuthorMarkup(a.author)}</article></main>`;}
function publicPostLockMarkup(slug){return `${publicPostHeaderMarkup()}<main class="post-lock-view"><div class="post-lock-backdrop"><section class="post-lock-sheet" role="dialog" aria-modal="true" aria-labelledby="post-lock-title"><div class="sheet-handle" aria-hidden="true"></div><span class="post-lock-icon">${icon('lock')}</span><span class="eyebrow">PRIVATE POST</span><h1 id="post-lock-title">This post is protected</h1><p class="post-lock-description">Enter the 6-digit password from the post owner to continue reading.</p><form id="post-unlock-form" data-slug="${esc(slug)}"><div class="post-passcode-inputs" role="group" aria-label="Six-digit post password">${Array.from({length:6},(_,i)=>`<input class="post-passcode-digit" type="text" inputmode="numeric" pattern="[0-9]*" maxlength="1" autocomplete="${i===0?'one-time-code':'off'}" aria-label="Digit ${i+1} of 6" data-post-password-digit="${i}" ${i===0?'autofocus':''} />`).join('')}</div><p class="post-unlock-error" id="post-unlock-error" role="alert" aria-live="polite"></p><button class="btn btn-primary post-unlock-button" type="submit">Unlock post</button></form><a class="post-lock-back" href="/" data-route="home">Back to Mylink</a></section></div></main>`;}
async function publicPostPage(slug){try{const {article}=await api(`/public/posts/${encodeURIComponent(slug)}`);return article.hasPassword?{markup:publicPostLockMarkup(slug),article:null}:{markup:`${publicPostHeaderMarkup()}${publicArticleMarkup(article)}`,article};}catch{return{markup:`${publicPostHeaderMarkup()}<main class="public-article post-not-found"><h1>Post not found</h1><p>This article may have been removed or its URL is incorrect.</p><a href="/" data-route="home">Return to Mylink</a></main>`,article:null};}}
function bindPublicPostLock(){const form=document.querySelector('#post-unlock-form');if(!form)return;const digits=[...form.querySelectorAll('[data-post-password-digit]')];const errorNode=form.querySelector('#post-unlock-error');digits.forEach((input,index)=>{input.addEventListener('input',()=>{const value=input.value.replace(/\D/g,'');if(value.length>1){[...value.slice(0,6)].forEach((digit,i)=>{if(digits[i])digits[i].value=digit;});digits[Math.min(value.length,5)]?.focus();return;}input.value=value;if(input.value)digits[index+1]?.focus();});input.addEventListener('keydown',event=>{if(event.key==='Backspace'&&!input.value&&index>0){digits[index-1].value='';digits[index-1].focus();}if(event.key==='ArrowLeft')digits[index-1]?.focus();if(event.key==='ArrowRight')digits[index+1]?.focus();});input.addEventListener('paste',event=>{event.preventDefault();const code=(event.clipboardData?.getData('text')||'').replace(/\D/g,'').slice(0,6);[...code].forEach((digit,i)=>{if(digits[i])digits[i].value=digit;});digits[Math.min(code.length,5)]?.focus();});});digits[0]?.focus();form.addEventListener('submit',async event=>{event.preventDefault();const password=digits.map(input=>input.value).join('');if(!/^\d{6}$/.test(password)){errorNode.textContent='Enter all 6 digits to unlock this post.';digits.find(input=>!input.value)?.focus();return;}const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Checking password…';errorNode.textContent='';try{const {article}=await api(`/public/posts/${encodeURIComponent(form.dataset.slug)}/unlock`,{method:'POST',body:{password}});app.innerHTML=`${publicPostHeaderMarkup()}${publicArticleMarkup(article)}`;startCreationViewTracking('posts',form.dataset.slug);showPageBannerAds(article,'post');}catch(error){errorNode.textContent=error.message;digits.forEach(input=>input.value='');digits[0]?.focus();button.disabled=false;button.textContent='Unlock post';}});}

