function bindPublicTreeLock(){const form=document.querySelector('#tree-unlock-form');if(!form)return;const digits=[...form.querySelectorAll('[data-tree-password-digit]')];const errorNode=form.querySelector('#tree-unlock-error');digits.forEach((input,index)=>{input.addEventListener('input',()=>{const value=input.value.replace(/\D/g,'');if(value.length>1){[...value.slice(0,6)].forEach((digit,i)=>{if(digits[i])digits[i].value=digit;});digits[Math.min(value.length,5)]?.focus();return;}input.value=value;if(input.value)digits[index+1]?.focus();});input.addEventListener('keydown',event=>{if(event.key==='Backspace'&&!input.value&&index>0){digits[index-1].value='';digits[index-1].focus();}if(event.key==='ArrowLeft')digits[index-1]?.focus();if(event.key==='ArrowRight')digits[index+1]?.focus();});input.addEventListener('paste',event=>{event.preventDefault();const code=(event.clipboardData?.getData('text')||'').replace(/\D/g,'').slice(0,6);[...code].forEach((digit,i)=>{if(digits[i])digits[i].value=digit;});digits[Math.min(code.length,5)]?.focus();});});digits[0]?.focus();form.addEventListener('submit',async event=>{event.preventDefault();const password=digits.map(input=>input.value).join('');if(!/^\d{6}$/.test(password)){errorNode.textContent='Enter all 6 digits to unlock this page.';digits.find(input=>!input.value)?.focus();return;}const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Checking password…';errorNode.textContent='';try{const {tree}=await api(`/public/trees/${encodeURIComponent(form.dataset.slug)}/unlock`,{method:'POST',body:{password}});app.innerHTML=`<main class="tree-public-page ${tree.theme?.showVisits===false?'tree-hide-visits':''} tree-theme-${esc(tree.theme?.name||'glass')}" style="${treeCanvasStyle(tree.theme||{})}"><div class="tree-public-brand">${brand()}</div>${treePreviewMarkup(tree)}<div class="tree-public-views">${Number(tree.viewCount||0).toLocaleString()} views</div></main>`;startCreationViewTracking('trees',form.dataset.slug);showPageBannerAds(tree,'tree');}catch(error){errorNode.textContent=error.message;digits.forEach(input=>input.value='');digits[0]?.focus();button.disabled=false;button.textContent='Unlock page';}});}

function publicTreeMarkup(tree={}){const theme=tree.theme||{};const classes='tree-public-page '+(theme.showVisits===false?'tree-hide-visits ':'')+'tree-theme-'+esc(theme.name||'glass');return '<main class="'+classes+'" data-tree-background-direct-link="'+esc(tree.treeBackgroundDirectLink||'')+'" style="'+treeCanvasStyle(theme)+'"><div class="tree-public-brand">'+brand()+'</div>'+treePreviewMarkup(tree)+'<div class="tree-public-views">'+Number(tree.viewCount||0).toLocaleString()+' views</div></main>';}
