function telegramBotFormMarkup(bot={},draft=false,index=0){
  const key=`${draft?'new':bot.id}-${index}`;
  return `<form class="form telegram-bot-form" data-bot-id="${esc(bot.id||'')}" id="telegram-bot-form-${esc(key)}"><div class="telegram-bot-card-head"><span class="telegram-bot-avatar">${icon('support')}</span><div><h4>${esc(bot.botName||`Telegram bot ${index+1}`)}</h4><small>${draft?'New bot setup':`Bot ID ${esc(bot.botId)}`}</small></div>${draft?'':`<button type="button" class="btn btn-danger btn-small" data-action="telegram-bot-delete" data-id="${esc(bot.id)}">Remove</button>`}</div><div class="field"><label for="telegram-bot-name-${esc(key)}">Telegram bot name</label><input id="telegram-bot-name-${esc(key)}" name="botName" type="text" maxlength="64" value="${esc(bot.botName||'')}" placeholder="My Telegram Storage Bot" required /></div><div class="field"><label for="telegram-bot-id-${esc(key)}">Telegram Bot ID</label><input id="telegram-bot-id-${esc(key)}" name="botId" type="text" inputmode="numeric" pattern="[0-9]{5,15}" maxlength="15" value="${esc(bot.botId||'')}" placeholder="123456789" required /></div><div class="field"><label for="telegram-bot-key-${esc(key)}">Telegram Bot API key</label><div class="telegram-key-field"><input id="telegram-bot-key-${esc(key)}" name="botApiKey" type="password" autocomplete="off" value="${esc(bot.botApiKey||'')}" placeholder="123456789:••••••••••••••••••••••••••" ${draft?'required':''} /><button type="button" class="telegram-key-toggle" data-action="toggle-password" data-target="telegram-bot-key-${esc(key)}" aria-label="Show API key">${icon('eye')}</button></div><small>Bot tokens are encrypted when saved.</small></div><div class="field"><label for="telegram-storage-channel-${esc(key)}">Storage channel ID</label><input id="telegram-storage-channel-${esc(key)}" name="storageChannelId" type="text" maxlength="60" value="${esc(bot.storageChannelId||'')}" placeholder="-1001234567890 or @channelname" /><small>Your bot must be an admin in this channel for storage to work.</small></div><div class="telegram-bot-form-actions"><button class="btn btn-primary" type="submit">${draft?'Add bot':'Save changes'}</button>${draft?'<button class="btn btn-outline" type="button" data-action="telegram-bot-cancel">Cancel</button>':''}</div></form>`;
}

