async function supportPage() {
  const data=await api('/support/tickets');
  return `<div class="welcome-row links-welcome support-welcome"><div><h2>Help &amp; support</h2><p>Get help from our team and follow every reply in one place.</p></div></div><div class="support-layout"><section class="panel links-panel support-form-panel" id="support-form-panel"><div class="links-toolbar support-panel-heading"><div><strong>Tell us how we can help</strong><p>Share a few details so we can route your request.</p></div></div><form class="form support-form" id="support-form"><div class="field"><label for="support-subject">Subject</label><input id="support-subject" name="subject" minlength="4" maxlength="120" placeholder="What do you need help with?" required /></div><div class="field"><label id="support-category-label">Category</label><div class="support-category-dropdown"><input type="hidden" name="category" value="general" /><button class="support-category-trigger" id="support-category-trigger" type="button" data-action="support-category-toggle" aria-labelledby="support-category-label support-category-value" aria-haspopup="listbox" aria-expanded="false"><span id="support-category-value">General</span>${icon('chevron')}</button><div class="support-category-menu" role="listbox" aria-labelledby="support-category-label" hidden>${['General','Account','Link review','Earnings','Withdrawal','Security'].map((name,i)=>`<button type="button" role="option" aria-selected="${i===0?'true':'false'}" class="support-category-option ${i===0?'is-selected':''}" data-action="support-category-select" data-value="${esc(name.toLowerCase())}">${esc(name)}${i===0?'<span>✓</span>':''}</button>`).join('')}</div></div></div><div class="field support-message-field"><label for="support-message">Message</label><textarea id="support-message" name="message" minlength="10" maxlength="3000" placeholder="Describe the issue and include any useful details…" required></textarea></div><div class="support-form-footer"><span>Your tickets are visible only to you and authorized support staff.</span><button class="btn btn-primary" type="submit">Submit ticket <span aria-hidden="true">→</span></button></div></form></section><section class="panel links-panel support-tickets-panel"><div class="links-toolbar support-panel-heading"><div><strong>Your tickets</strong><p>Check the latest status or open a conversation.</p></div><span class="links-count">${data.items.length} ${data.items.length===1?'ticket':'tickets'}</span></div>${data.items.length?`<div class="support-ticket-list">${data.items.map(x=>`<article class="support-ticket-row"><span class="support-ticket-icon">${icon('support')}</span><div class="support-ticket-main"><h3>${esc(x.subject)}</h3><span>Updated ${dateTimeFmt(x.updated_at)}</span></div><div class="support-ticket-meta">${statusPill(x.status)}<button class="btn btn-outline btn-small" data-action="open-ticket" data-id="${esc(x.id)}">View conversation <span aria-hidden="true">→</span></button></div></article>`).join('')}</div>`:`<div class="support-empty"><span>${icon('support')}</span><h3>No tickets yet</h3><p>When you contact support, your conversation and updates will appear here.</p></div>`}</section></div><div id="ticket-detail"></div>`;
}

async function adminDashboard() {
  const d=await api('/admin/dashboard');
  const totals=d.analytics.totals, recent=d.traffic14Days.totals, today=d.trafficToday.totals;
  const num=value=>Number(value||0).toLocaleString();
  const rate=(value,base)=>base?Math.round(Number(value||0)/Number(base)*100):0;
  const totalCreates=Number(d.creations.total||0);
  const mix=[
    ['Short links',d.creations.links,d.creations.activeLinks,'link'],
    ['Files',d.creations.files,d.creations.activeFiles,'file'],
    ['Trees',d.creations.trees.total,d.creations.trees.active,'tree'],
    ['Posts',d.creations.posts.total,d.creations.posts.published,'file'],
  ];
  const typeName={link:'Link',file:'File',tree:'Tree',post:'Post'};
  const actionCards=[
    ['Unverified users',Number(d.users.pendingVerification||0),'waiting for email verification','Review member accounts','admin-users','users'],
    ['Withdrawals',Number(d.withdrawals.pendingCount||0),'requests need review',money(d.withdrawals.pendingPaise),'admin-withdrawals','wallet'],
    ['Support tickets',Number(d.operations.supportOpen||0),'open or in progress','Review conversations','admin-support','support'],
    ['Flagged links',Number(d.operations.flaggedLinks||0),'need moderation','Review reported links','admin-creations','shield'],
    ['Draft posts',Number(d.operations.draftPosts||0),'not published yet','Open blog management','admin-blogs','file'],
  ];
  const performing=d.performingCreations||[];
  const funnelRows=Array.from({length:5},(_,index)=>{
    const x=d.funnel.find(item=>Number(item.position)===index+1)||{};
    const activated=Number(x.activated||0),completed=Number(x.completed||0),verified=Number(x.verified||0);
    return `<div class="admin-funnel-row"><div class="admin-funnel-step"><span>${String(index+1).padStart(2,'0')}</span><b>Step ${index+1}</b></div><div class="admin-funnel-track"><span style="width:${activated?Math.max(1,Math.min(100,completed/activated*100)):0}%"></span></div><div class="admin-funnel-values"><b>${num(completed)} <small>done</small></b><span>${num(activated)} started · ${num(verified)} verified</span></div></div>`;
  }).join('');
  const performanceRows=performing.length?performing.map(item=>`<div class="admin-performing-row"><span class="admin-performing-icon admin-performing-${esc(item.type)}">${icon(item.type==='tree'?'tree':item.type==='file'?'file':item.type==='post'?'article':'link')}</span><div class="admin-performing-main"><b>${esc(item.title)}</b><span>${esc(typeName[item.type]||'Creation')} · ${esc(item.path)}</span></div><span class="admin-performing-visits"><b>${num(item.visits)}</b><small>visits</small></span>${statusPill(item.status)}</div>`).join(''):`<div class="empty-state">Performing creations will appear after they receive visits.</div>`;
  const operations=actionCards.map(([title,count,detail,value,route,iconName])=>`<a class="admin-action-card" href="/#${route}" data-route="${route}"><span class="admin-action-icon">${icon(iconName)}</span><span class="admin-action-copy"><b>${esc(title)}</b><small>${esc(detail)}</small></span><strong>${num(count)}</strong><span class="admin-action-value">${esc(value)}</span></a>`).join('');
  return `<div class="admin-overview-page"><div class="welcome-row admin-overview-heading"><div><span class="eyebrow">PLATFORM HEALTH</span><h2>Admin overview</h2><p>Detailed account, creation, traffic, revenue, and review activity.</p></div><div class="admin-overview-heading-actions"><span class="admin-live-pill"><i></i> Live data</span><a class="btn btn-outline" href="/#admin-reports" data-route="admin-reports">${icon('chart')} Reports</a></div></div>
    <section class="admin-overview-summary-grid" aria-label="Platform summary">${metricCard('Members',num(d.users.total),icon('users'),`${num(d.users.active)} active · ${num(d.users.verified)} verified · ${num(d.users.newToday)} today`)}${metricCard('All creations',num(totalCreates),icon('grid'),`${num(d.creations.links)} links · ${num(d.creations.files)} files · ${num(d.creations.trees.total)} trees · ${num(d.creations.posts.total)} posts`)}${metricCard('Total visits',num(totals.rawVisits),icon('chart'),`${num(recent.rawVisits)} in 14 days · ${num(today.rawVisits)} today`)}${metricCard('Destination clicks',num(totals.eligibleClicks),icon('check'),`${rate(totals.eligibleClicks,totals.rawVisits)}% of visits marked eligible`)}</section>
    <section class="admin-overview-section"><div class="admin-overview-section-heading"><div><span class="eyebrow">CONTENT LIBRARY</span><h3>Creation breakdown</h3><p>Current published and active inventory across every creator format.</p></div><a href="/#admin-creations" data-route="admin-creations">Review creations ${icon('arrow')}</a></div><div class="admin-creation-grid">${mix.map(([label,total,active,iconName])=>`<article class="admin-creation-card"><span class="admin-creation-icon">${icon(iconName)}</span><div class="admin-creation-copy"><span>${esc(label)}</span><b>${num(total)}</b><small>${label==='Posts'?`${num(active)} published · ${num(d.creations.posts.drafts)} drafts`:`${num(active)} active${label==='Trees'?` · ${num(d.creations.trees.paused)} paused`:''}`}</small></div></article>`).join('')}</div></section>
    <section class="admin-overview-section"><div class="admin-overview-section-heading"><div><span class="eyebrow">TRAFFIC &amp; CONVERSION</span><h3>Traffic performance</h3><p>${num(recent.rawVisits)} visits over the last 14 days; ${num(today.rawVisits)} recorded today.</p></div></div><div class="admin-overview-traffic-grid"><section class="panel admin-overview-traffic-panel"><div class="panel-header"><div><h3>Daily visit trend</h3><p>Recorded link visits · last 14 days</p></div><span class="admin-overview-period">14 days</span></div>${overviewTrafficMarkup(overviewTrafficWindow(d.traffic14Days.daily,14),'admin-traffic-chart')}</section><section class="panel admin-overview-quality-panel"><div class="panel-header"><div><h3>Traffic quality</h3><p>All-time event totals</p></div><span class="admin-quality-mark">${icon('shield')}</span></div><div class="admin-overview-data-list"><div><span>Unique sessions</span><b>${num(totals.uniqueVisitors)}</b></div><div><span>Eligible destination clicks</span><b>${num(totals.eligibleClicks)}</b></div><div><span>Invalid or rejected visits</span><b>${num(totals.invalidTraffic)}</b></div><div><span>Unlock completions</span><b>${num(totals.unlockCompletions)}</b></div><div><span>Successful redirects</span><b>${num(totals.redirects)}</b></div></div></section></div></section>
    <section class="admin-overview-section"><div class="admin-overview-section-heading"><div><span class="eyebrow">FINANCIAL SNAPSHOT</span><h3>Earnings and payouts</h3><p>USD ledger totals. Pending and held balances are not approved payouts.</p></div><a href="/#admin-withdrawals" data-route="admin-withdrawals">Review withdrawals ${icon('arrow')}</a></div><div class="admin-finance-grid">${metricCard('Pending earnings',money(d.earnings.pending),icon('clock'),`${num(d.earnings.reviewCount)} entries awaiting review`,'admin-finance-pending')}${metricCard('On hold',money(d.earnings.onHold),icon('pause'), 'Ledger entries held for review')}${metricCard('Approved earnings',money(d.earnings.approved),icon('check'), 'Approved ledger balance')}${metricCard('Paid out',money(d.earnings.paid),icon('wallet'),'Recorded payout ledger total')}</div></section>
    <section class="admin-overview-section"><div class="admin-overview-section-heading"><div><span class="eyebrow">ADMIN WORK QUEUE</span><h3>Items needing attention</h3><p>Jump directly to open reviews and platform follow-ups.</p></div></div><div class="admin-action-grid">${operations}</div></section>
    <div class="admin-overview-bottom-grid"><section class="panel admin-overview-funnel-panel"><div class="panel-header"><div><h3>Unlock funnel</h3><p>Visitor starts, acknowledgements, and provider verification by step.</p></div></div><div class="admin-funnel-list">${funnelRows}</div></section><section class="panel admin-overview-performing-panel"><div class="panel-header"><div><h3>Top performing creations</h3><p>Mixed links, files, trees, and posts ranked by visits.</p></div><a href="/#admin-creations" data-route="admin-creations">View all</a></div><div class="admin-performing-list">${performanceRows}</div></section></div>
    <div class="admin-overview-footnote">Snapshot generated ${dateTimeFmt(d.generatedAt)} · New visits and financial records update as they are recorded.</div></div>`;
}

async function adminUsersPage() {
  const params=new URLSearchParams(location.search),q=params.get('q')||'',status=params.get('status')||'',pageValue=Number(params.get('page')||1),page=Number.isInteger(pageValue)&&pageValue>0?pageValue:1;
  const data=await api(`/admin/users?q=${encodeURIComponent(q)}&status=${encodeURIComponent(status)}&page=${page}&limit=20`),summary=data.summary||{};
  const statusOptions=[['','All accounts'],['active','Active'],['pending_verification','Needs verification'],['suspended','Suspended'],['banned','Banned'],['closed','Closed']];
  const userReviewButton=user=>`<button type="button" class="btn btn-outline btn-small admin-user-review-button" data-action="admin-user-review" data-id="${esc(user.id)}" data-email="${esc(user.email)}" data-name="${esc(user.display_name)}" data-role="${esc(user.role)}" data-status="${esc(user.status)}" data-public-id="${esc(user.public_id||'')}" data-links="${Number(user.link_count||0)}" data-files="${Number(user.file_count||0)}" data-trees="${Number(user.tree_count||0)}" data-posts="${Number(user.post_count||0)}" data-visits="${Number(user.raw_visits||0)}" data-earnings="${Number(user.earnings_paise||0)}" data-balance="${Number(user.balance_paise||0)}" data-reserved="${Number(user.reserved_paise||0)}" data-created="${esc(user.created_at||'')}" data-verified="${esc(user.verified_at||'')}">${icon('users')} Review account</button>`;
  const userName=user=>`<div class="admin-user-identity"><span class="admin-user-avatar">${esc(String(user.display_name||user.email||'U').trim().split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase())}</span><span><b>${esc(user.display_name||'Member')}</b><small>${esc(user.email)}</small><small class="admin-user-public-id">${user.public_id?`ID ${esc(user.public_id)}`:esc(user.role)}</small></span></div>`;
  const rows=data.items.map(user=>`<tr><td>${userName(user)}</td><td><div class="admin-user-counts"><span><b>${Number(user.link_count||0)}</b> links</span><span><b>${Number(user.file_count||0)}</b> files</span><span><b>${Number(user.tree_count||0)}</b> trees</span><span><b>${Number(user.post_count||0)}</b> posts</span></div></td><td><b>${Number(user.raw_visits||0).toLocaleString()}</b></td><td><b class="admin-user-balance">${money(user.balance_paise)}</b><small class="admin-user-reserved">${money(user.reserved_paise)} reserved</small></td><td>${statusPill(user.status)}</td><td>${dateFmt(user.created_at)}</td><td>${userReviewButton(user)}</td></tr>`).join('');
  const cards=data.items.map(user=>`<article class="admin-user-card"><div class="admin-user-card-head">${userName(user)}${statusPill(user.status)}</div><div class="admin-user-card-stats"><span><small>Creations</small><b>${Number(user.creation_count||0).toLocaleString()}</b><em>${Number(user.link_count||0)} links · ${Number(user.file_count||0)} files · ${Number(user.tree_count||0)} trees · ${Number(user.post_count||0)} posts</em></span><span><small>Visits</small><b>${Number(user.raw_visits||0).toLocaleString()}</b></span><span><small>Balance</small><b>${money(user.balance_paise)}</b><em>${money(user.reserved_paise)} reserved</em></span><span><small>Joined</small><b>${dateFmt(user.created_at)}</b></span></div>${userReviewButton(user)}</article>`).join('');
  const first=data.total?(data.page-1)*data.pageSize+1:0,last=Math.min(data.page*data.pageSize,data.total);
  const pagination=`<div class="admin-users-pagination"><span>Showing ${first}–${last} of ${Number(data.total).toLocaleString()} accounts</span><div><button type="button" class="btn btn-outline btn-small" data-action="admin-user-page" data-page="${Math.max(1,data.page-1)}" ${data.page<=1?'disabled':''}>${icon('arrow')} Previous</button><span>Page ${data.page} of ${data.pages}</span><button type="button" class="btn btn-outline btn-small" data-action="admin-user-page" data-page="${Math.min(data.pages,data.page+1)}" ${data.page>=data.pages?'disabled':''}>Next ${icon('arrow')}</button></div></div>`;
  return `<div class="admin-users-page"><div class="welcome-row admin-users-heading"><div><h2>Users</h2><p>Manage member access, balances, passwords, and account safety.</p></div><span class="admin-users-total">${Number(summary.total||0).toLocaleString()} accounts</span></div><section class="admin-users-summary">${metricCard('All users',Number(summary.total||0).toLocaleString(),icon('users'),'Every account on the platform')}${metricCard('Active',Number(summary.active||0).toLocaleString(),icon('check'),'Accounts with access')}${metricCard('Needs verification',Number(summary.pending||0).toLocaleString(),icon('clock'),'Email verification pending')}${metricCard('Restricted',Number(summary.restricted||0).toLocaleString(),icon('shield'),`${Number(summary.closed||0).toLocaleString()} closed accounts`)}</section><section class="panel admin-users-panel"><form class="admin-users-toolbar" id="admin-user-search"><label class="admin-users-search"><span>${icon('chart')}</span><input name="q" placeholder="Search name, email, user ID" value="${esc(q)}"/><button class="btn btn-outline btn-small" type="submit">Search</button></label><label class="admin-users-filter"><span>Account status</span><select name="status" class="select-input">${statusOptions.map(([value,label])=>`<option value="${value}" ${status===value?'selected':''}>${label}</option>`).join('')}</select></label></form><div class="admin-users-table-wrap">${data.items.length?`<div class="table-wrap"><table class="data-table admin-users-table"><thead><tr><th>Account</th><th>Creations</th><th>Visits</th><th>Available balance</th><th>Status</th><th>Joined</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="admin-users-empty">No accounts match these filters.</div>'}</div><div class="admin-users-mobile-list">${cards||'<div class="admin-users-empty">No accounts match these filters.</div>'}</div>${pagination}</section></div>`;
}

function openAdminUserReview(button){
  const {id,email,name,role,status,publicId,created,verified}=button.dataset;
  const counts={links:Number(button.dataset.links||0),files:Number(button.dataset.files||0),trees:Number(button.dataset.trees||0),posts:Number(button.dataset.posts||0),visits:Number(button.dataset.visits||0)};
  const balance=Number(button.dataset.balance||0),earnings=Number(button.dataset.earnings||0),reserved=Number(button.dataset.reserved||0),isDeleted=email.endsWith('@deleted.invalid'),canManage=role==='user'&&status!=='closed'&&!isDeleted;
  const choices=status==='pending_verification'?['pending_verification','active','suspended','banned','closed']:['active','suspended','banned','closed'];
  const accessPanel=isDeleted?`<section class="admin-user-tool-section admin-user-danger-section"><div class="admin-user-tool-heading"><span class="admin-user-tool-icon">${icon('shield')}</span><div><h4>Account deleted</h4><p>This account is anonymized and cannot be reactivated. Its audit and financial history remains preserved.</p></div></div></section>`:`<section class="admin-user-tool-section"><div class="admin-user-tool-heading"><span class="admin-user-tool-icon">${icon('shield')}</span><div><h4>Account access</h4><p>Update status and revoke access when needed.</p></div></div><form id="admin-user-status-form" class="form" data-id="${esc(id)}" data-current="${esc(status)}"><div class="field-row"><div class="field"><label>Account status</label><select name="status" class="select-input">${choices.map(value=>`<option value="${value}" ${status===value?'selected':''}>${value.replaceAll('_',' ')}</option>`).join('')}</select></div><div class="field"><label>Reason for audit</label><input name="reason" minlength="5" maxlength="500" placeholder="Required for status changes" required/></div></div><button class="btn btn-primary" type="submit">Save account status</button></form></section>`;
  showModal(`<div class="sheet-handle" aria-hidden="true"></div><div class="admin-user-review-head"><div><span class="eyebrow">ACCOUNT REVIEW</span><h3>${esc(name||'Member')}</h3><p>${esc(email)} · ${statusPill(status)}</p></div><button type="button" class="icon-btn" data-action="close-modal" aria-label="Close review">×</button></div><div class="admin-user-review-grid"><div><small>Public ID</small><b>${esc(publicId||'—')}</b></div><div><small>Joined</small><b>${dateFmt(created)}</b></div><div><small>Verification</small><b>${verified?'Verified':'Not verified'}</b></div><div><small>Traffic</small><b>${counts.visits.toLocaleString()} visits</b></div></div><div class="admin-user-creation-breakdown"><span><b>${counts.links}</b> Links</span><span><b>${counts.files}</b> Files</span><span><b>${counts.trees}</b> Trees</span><span><b>${counts.posts}</b> Posts</span></div><div class="admin-user-finance-summary"><div><small>Approved balance</small><b>${money(balance)}</b></div><div><small>Pending / total earnings</small><b>${money(earnings)}</b></div><div><small>Reserved withdrawals</small><b>${money(reserved)}</b></div></div>${accessPanel}<section class="admin-user-tool-section"><div class="admin-user-tool-heading"><span class="admin-user-tool-icon">${icon('wallet')}</span><div><h4>Manage balance</h4><p>Record an auditable USD credit or debit. Use a minus sign to subtract.</p></div></div><form id="admin-user-balance-form" class="form" data-id="${esc(id)}"><div class="field-row"><div class="field"><label>Adjustment amount (${esc(state.settings.currency||'USD')})</label><input name="amount" type="number" step="0.01" placeholder="e.g. 5.00 or -2.00" required/></div><div class="field"><label>Reason</label><input name="reason" minlength="5" maxlength="500" placeholder="Why is this adjustment needed?" required/></div></div><button class="btn btn-outline" type="submit">${icon('plus')} Record balance adjustment</button></form></section>${canManage?`<section class="admin-user-tool-section"><div class="admin-user-tool-heading"><span class="admin-user-tool-icon">${icon('lock')}</span><div><h4>Reset password</h4><p>Set a temporary password and end all current sessions. Share it with the account owner securely.</p></div></div><form id="admin-user-password-form" class="form" data-id="${esc(id)}"><div class="field-row"><div class="field"><label>New password</label><input name="password" type="password" minlength="10" maxlength="128" autocomplete="new-password" required/></div><div class="field"><label>Confirm password</label><input name="confirmPassword" type="password" minlength="10" maxlength="128" autocomplete="new-password" required/></div></div><div class="field"><label>Reason for audit</label><input name="reason" minlength="5" maxlength="500" required/></div><button class="btn btn-outline" type="submit">${icon('lock')} Set new password</button></form></section>`:''}${role==='user'&&status!=='closed'&&!isDeleted?`<section class="admin-user-tool-section admin-user-danger-section"><div class="admin-user-tool-heading"><span class="admin-user-tool-icon">${icon('trash')}</span><div><h4>Delete account</h4><p>Closes access, anonymizes profile and payout details, disables public creations, and cancels pending withdrawals. Financial and audit history is retained.</p></div></div><form id="admin-user-delete-form" class="form" data-id="${esc(id)}" data-email="${esc(email)}"><div class="field-row"><div class="field"><label>Type the account email to confirm</label><input name="confirmEmail" type="email" autocomplete="off" required/></div><div class="field"><label>Reason for audit</label><input name="reason" minlength="5" maxlength="500" required/></div></div><button class="btn btn-danger" type="submit">${icon('trash')} Delete and anonymize account</button></form></section>`:''}`, 'edit-sheet admin-user-review-sheet');
  document.querySelector('#admin-user-status-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,values=Object.fromEntries(new FormData(form));if(values.status===form.dataset.current){toast('Choose a different account status to save.','error');return;}try{await api(`/admin/users/${encodeURIComponent(form.dataset.id)}/status`,{method:'PATCH',body:values});toast('Account status updated.');closeModal();renderRoute();}catch(error){toast(error.message,'error');}});
  document.querySelector('#admin-user-balance-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,values=Object.fromEntries(new FormData(form)),amountPaise=Math.round(Number(values.amount)*100);if(!Number.isSafeInteger(amountPaise)||!amountPaise){toast('Enter a non-zero amount.','error');return;}try{await api('/admin/earnings/adjustments',{method:'POST',body:{userId:form.dataset.id,amountPaise,reason:values.reason}});toast('Balance adjustment recorded.');closeModal();renderRoute();}catch(error){toast(error.message,'error');}});
  document.querySelector('#admin-user-password-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,values=Object.fromEntries(new FormData(form));if(values.password!==values.confirmPassword){toast('Passwords do not match.','error');return;}delete values.confirmPassword;try{await api(`/admin/users/${encodeURIComponent(form.dataset.id)}/password`,{method:'PATCH',body:values});toast('Password updated and existing sessions ended.');closeModal();renderRoute();}catch(error){toast(error.message,'error');}});
  document.querySelector('#admin-user-delete-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,values=Object.fromEntries(new FormData(form));if(values.confirmEmail.trim().toLowerCase()!==form.dataset.email.trim().toLowerCase()){toast('Enter the account email exactly to confirm deletion.','error');return;}if(!confirm('Delete this account, remove its profile and payout details, and disable its public creations?'))return;try{await api(`/admin/users/${encodeURIComponent(form.dataset.id)}/delete`,{method:'POST',body:values});toast('Account deleted and anonymized. Financial history retained.');closeModal();renderRoute();}catch(error){toast(error.message,'error');}});
}

async function adminLinksPage() {
  return adminCreationsPage('links');
}

async function adminCreationsPage(defaultType='links') {
  const params=new URLSearchParams(location.search),type=['links','files','trees','posts'].includes(params.get('type'))?params.get('type'):defaultType;
  const q=params.get('q')||'',status=params.get('status')||'',pageValue=Number(params.get('page')||1),page=Number.isInteger(pageValue)&&pageValue>0?pageValue:1;
  const data=await api(`/admin/creations?type=${encodeURIComponent(type)}&q=${encodeURIComponent(q)}&status=${encodeURIComponent(status)}&page=${page}&limit=20`);
  const labels={links:'Links',files:'Files',trees:'Trees',posts:'Posts'},icons={links:'link',files:'file',trees:'tree',posts:'article'};
  const statusOptions={links:['active','paused','disabled','flagged','expired'],files:['active','paused','disabled','flagged','expired'],trees:['active','paused'],posts:['draft','published']}[type];
  const tabs=Object.keys(labels).map(key=>`<button type="button" role="tab" aria-selected="${type===key}" class="admin-creations-tab ${type===key?'is-active':''}" data-action="admin-creation-type" data-type="${key}"><span>${icon(icons[key])}${labels[key]}</span><b>${Number(data.typeCounts[key]||0).toLocaleString()}</b></button>`).join('');
  const ownerCell=item=>`<div class="admin-creation-owner"><b>${esc(item.owner_name||'Member')}</b><span>${esc(item.owner_email||'')}</span><small>${esc(item.owner_status||'unknown')} account</small></div>`;
  const targetCell=item=>type==='links'||type==='files'?`<a class="admin-creation-target" href="${esc(item.destination_url||'#')}" target="_blank" rel="noopener noreferrer" title="${esc(item.destination_url||'')}">${esc(item.destination_url||'—')}</a>`:`<span class="admin-creation-target admin-creation-slug">/${esc(item.slug||'')}</span>`;
  const reviewButton=item=>`<button type="button" class="btn btn-outline btn-small admin-creation-review-button" data-action="admin-creation-review" data-id="${esc(item.id)}" data-type="${esc(item.type)}" data-title="${esc(item.title)}" data-slug="${esc(item.slug)}" data-path="${esc(item.path)}" data-destination="${esc(item.destination_url||'')}" data-status="${esc(item.status)}" data-visits="${Number(item.visits||0)}" data-owner-id="${esc(item.owner_id)}" data-owner-name="${esc(item.owner_name)}" data-owner-email="${esc(item.owner_email)}" data-owner-status="${esc(item.owner_status)}" data-owner-role="${esc(item.owner_role)}">${icon('shield')} Review</button>`;
  const desktopRows=data.items.map(item=>`<tr><td><div class="admin-creation-title-cell"><span class="admin-creation-row-icon type-${esc(item.type)}">${icon(icons[item.type])}</span><span><b>${esc(item.title)}</b><small>${esc(item.slug||'')}</small></span></div></td><td>${ownerCell(item)}</td><td>${targetCell(item)}</td><td><strong>${Number(item.visits||0).toLocaleString()}</strong></td><td>${statusPill(item.status)}</td><td>${dateFmt(item.created_at)}</td><td>${reviewButton(item)}</td></tr>`).join('');
  const mobileRows=data.items.map(item=>`<article class="admin-creation-mobile-card"><div class="admin-creation-mobile-top"><div class="admin-creation-title-cell"><span class="admin-creation-row-icon type-${esc(item.type)}">${icon(icons[item.type])}</span><span><b>${esc(item.title)}</b><small>${esc(item.slug||'')}</small></span></div>${statusPill(item.status)}</div><div class="admin-creation-mobile-owner">${ownerCell(item)}</div><div class="admin-creation-mobile-meta"><span><small>Visits</small><b>${Number(item.visits||0).toLocaleString()}</b></span><span><small>Created</small><b>${dateFmt(item.created_at)}</b></span></div>${targetCell(item)}${reviewButton(item)}</article>`).join('');
  const first=data.total?(data.page-1)*data.pageSize+1:0,last=Math.min(data.page*data.pageSize,data.total);
  const pagination=`<div class="admin-creations-pagination"><span>Showing ${first}–${last} of ${Number(data.total).toLocaleString()}</span><div><button type="button" class="btn btn-outline btn-small" data-action="admin-creation-page" data-page="${Math.max(1,data.page-1)}" ${data.page<=1?'disabled':''}>${icon('arrow')} Previous</button><span>Page ${data.page} of ${data.pages}</span><button type="button" class="btn btn-outline btn-small" data-action="admin-creation-page" data-page="${Math.min(data.pages,data.page+1)}" ${data.page>=data.pages?'disabled':''}>Next ${icon('arrow')}</button></div></div>`;
  return `<div class="admin-creations-page"><div class="welcome-row admin-creations-heading"><div><h2>Users creations</h2><p>Review and manage links, files, trees, and posts from every user.</p></div><span class="admin-creations-total">${Number(Object.values(data.typeCounts).reduce((sum,value)=>sum+Number(value||0),0)).toLocaleString()} total creations</span></div><nav class="admin-creations-tabs" role="tablist" aria-label="Creation types">${tabs}</nav><section class="panel admin-creations-panel"><form class="admin-creations-toolbar" id="admin-creation-search"><label class="admin-creations-search"><span>${icon('chart')}</span><input name="q" value="${esc(q)}" placeholder="Search title, slug, destination, or user"/><button class="btn btn-outline btn-small" type="submit">Search</button></label><label class="admin-creations-status-filter"><span>Status</span><select name="status" class="select-input"><option value="" ${!status?'selected':''}>All statuses</option>${statusOptions.map(option=>`<option value="${option}" ${status===option?'selected':''}>${option.replaceAll('_',' ')}</option>`).join('')}</select></label></form><div class="admin-creation-table-wrap"><div class="table-wrap"><table class="data-table admin-creations-table"><thead><tr><th>Creation</th><th>Owner</th><th>${type==='links'||type==='files'?'Destination':'Public URL'}</th><th>Visits</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${desktopRows||`<tr><td colspan="7"><div class="empty-state"><b>No ${labels[type].toLowerCase()} found</b>Try another search or status filter.</div></td></tr>`}</tbody></table></div></div><div class="admin-creation-mobile-list">${mobileRows||'<div class="empty-state"><b>No creations found</b>Try another search or status filter.</div>'}</div>${pagination}</section></div>`;
}

async function adminUnlockPage() {
  const d=await api('/admin/settings');
  return `<div class="unlock-admin-page"><div class="welcome-row admin-ads-heading"><div><h2>Unlock &amp; ads</h2><p>Manage the five visitor steps, their destinations, and Link Tree background traffic.</p></div></div><div class="unlock-admin-guide"><span>${icon('warning')}</span><p><b>How redirects work</b><small>Click opens each step’s Direct Link in a new tab. Next and Unlock control the original tab’s destination.</small></p></div><form id="steps-form" class="form unlock-admin-form"><section class="unlock-admin-section"><div class="unlock-admin-section-head"><div><span class="eyebrow">STEP FLOW</span><h3>Step redirect settings</h3><p>Each step has its own Direct Link and previous-tab URL.</p></div><span class="unlock-admin-count">${d.steps.length} steps</span></div><div class="unlock-admin-step-grid">${d.steps.map(s=>{const nextTabUrl=s.next_tab_url||'';return `<article class="step-setting unlock-admin-step"><div class="step-config-title"><span class="step-config-number">${String(s.position).padStart(2,'0')}</span><div><h4>Step ${s.position}</h4><small>Ad click and Next destinations</small></div><span class="step-url-state" data-url-state="${s.position}">${s.destination_url?.startsWith('http')?'URL configured':'URL needed'}</span></div><div class="field step-url-field"><label>Ad Direct Link <span>Opens in a new tab</span></label><input data-step-url="${s.position}" name="destination-${s.position}" type="url" value="${esc(s.destination_url)}" placeholder="https://your-direct-link.example" /><small class="help">Opened when the visitor clicks this step.</small></div><div class="field step-url-field"><label>Next · previous-tab URL</label><input name="next-tab-${s.position}" type="url" value="${esc(nextTabUrl)}" placeholder="https://your-next-tab-destination.example" /><small class="help">The original step tab navigates here after Next.</small></div><div class="field"><label>Step title</label><input name="title-${s.position}" value="${esc(s.title)}" maxlength="80" required /></div><div class="field"><label>Button label</label><input name="label-${s.position}" value="${esc(s.button_label)}" maxlength="80" required /></div><div class="field unlock-step-instruction"><label>Visitor instruction</label><input name="instruction-${s.position}" value="${esc(s.instruction)}" maxlength="240" required /></div><label class="toggle-row unlock-step-toggle"><input type="checkbox" name="enabled-${s.position}" ${s.enabled?'checked':''}/> Enable step ${s.position}</label><input type="hidden" name="policy-${s.position}" value="${esc(s.policy)}" /><input type="hidden" name="integration-${s.position}" value="${esc(s.integration_id||'')}" /><input type="hidden" name="retry-${s.position}" value="${Number(s.retry_limit)}" /><input type="hidden" name="order-${s.position}" value="${Number(s.display_order)}" /></article>`;}).join('')}</div></section><section class="unlock-admin-section"><div class="unlock-admin-section-head"><div><span class="eyebrow">GLOBAL DESTINATIONS</span><h3>Final &amp; Link Tree links</h3><p>These URLs apply to the final unlock action and public Link Tree pages.</p></div></div><div class="unlock-admin-global-grid"><article class="unlock-admin-global-card"><div class="unlock-admin-global-icon">${icon('arrow')}</div><div class="unlock-admin-global-copy"><h4>Unlock previous-tab URL</h4><p>The original tab navigates here when the final destination is opened.</p></div><div class="field"><label>Previous-tab destination</label><input name="unlockPreviousTabUrl" type="url" value="${esc(d.unlockPreviousTabUrl||'')}" placeholder="https://your-unlock-destination.example" /><small>Leave empty to use Step 5’s previous-tab URL.</small></div></article><article class="unlock-admin-global-card tree-background-direct-card"><div class="unlock-admin-global-icon">${icon('tree')}</div><div class="unlock-admin-global-copy"><h4>Link Tree background Direct Link</h4><p>Visitors who click/tap an empty area of a public Link Tree open this URL in a new tab. Tree buttons and social links remain unchanged.</p></div><div class="field"><label>Background Direct Link</label><input name="treeBackgroundDirectLink" type="url" value="${esc(d.treeBackgroundDirectLink||'')}" placeholder="https://your-link-tree-direct-link.example" /><small>Leave blank to turn this Link Tree background ad off.</small></div></article></div></section><div class="unlock-admin-savebar"><span>Changes apply to new page visits after saving.</span><button class="btn btn-primary" type="submit">${icon('check')} Save redirect settings</button></div></form></div>`;
}

function adsScriptToggle(name,enabled,label){const on=Boolean(enabled);return `<span class="ads-toggle-control"><input type="hidden" name="${esc(name)}" value="${on?'true':'false'}"/><button type="button" class="ads-toggle-switch ${on?'is-on':''}" role="switch" aria-checked="${on}" aria-label="${on?'Turn off':'Turn on'} ${esc(label)}" data-action="ads-script-toggle" data-name="${esc(name)}"><span></span></button><span class="ads-toggle-status">${on?'On':'Off'}</span></span>`;}
function contentAdScriptFormMarkup(contentType,title,items){const scripts=[1,2].map(slot=>items?.find(item=>Number(item.slot)===slot)||{slot,script:'',enabled:true});const providers=['AdsGram','Monetag'];return `<section class="panel content-ads-panel"><div class="panel-header"><div><span class="eyebrow">${esc(title.toUpperCase())} ADS</span><h3>${contentType==='files'?'File unlock ads':`${esc(title)} page scripts`}</h3><p>${contentType==='files'?'A random enabled provider ad is selected for each Telegram file unlock visit.':'These creatives are independent from Links and unlock-step ads.'}</p></div><span class="unlock-admin-count">2 script slots</span></div>${contentType==='files'?'<div class="notice warning file-ad-provider-note">Paste the provider script with your AdsGram Block ID or Monetag Zone ID. These networks require the page to open inside a Telegram Mini App.</div>':''}<form class="form content-ad-scripts-form" data-content-type="${contentType}">${scripts.map(item=>{const provider=contentType==='files'?providers[item.slot-1]:`Ad script ${item.slot}`;return `<article class="content-ad-script-card"><div class="content-ad-script-head"><div class="content-ad-script-number">0${item.slot}</div><div><h4>${provider}</h4><p>${contentType==='files'?'Selected randomly on file unlock visits.':`Shown in its own timed interstitial on ${esc(title.toLowerCase())} pages.`}</p></div>${adsScriptToggle(`enabled-${item.slot}`,item.enabled,`${title} ad ${item.slot}`)}</div><div class="field"><label for="${contentType}-script-${item.slot}">${contentType==='files'?`${provider} SDK / ad script`:'HTML / ad network script'}</label><textarea id="${contentType}-script-${item.slot}" name="script-${item.slot}" rows="8" maxlength="50000" spellcheck="false" placeholder="${contentType==='files'?`Paste your ${provider} publisher snippet, including its ID`:`Paste one ${esc(title.toLowerCase())} ad script here`}">${esc(item.script||'')}</textarea><small>Up to 50,000 characters. Toggle this slot off to keep its code saved without showing it.</small></div></article>`;}).join('')}<div class="content-ad-save-row"><span>${contentType==='files'?'Enable both providers to rotate randomly.':'Script 1 and Script 2 have separate on/off controls.'}</span><button class="btn btn-primary" type="submit">Save ${esc(title.toLowerCase())} ads</button></div></form></section>`;}
async function adminAdsScriptsPage() {
  const data=await api('/admin/ads-scripts');const params=new URLSearchParams(location.search);const requested=params.get('section')||'links';const section=['links','posts','trees','files'].includes(requested)?requested:'links';
  const sectionMeta={links:['Links','link'],posts:['Posts','file'],trees:['Trees','tree'],files:['Files','file']};
  const tabs=Object.entries(sectionMeta).map(([key,[label,iconName]])=>`<button type="button" role="tab" aria-selected="${section===key}" class="admin-ads-tab ${section===key?'is-active':''}" data-action="admin-ads-section" data-section="${key}">${icon(iconName)}<span>${label}</span></button>`).join('');
  let content='';
  if(section==='links')content=`<section class="panel admin-ads-links-panel"><div class="panel-header"><div><span class="eyebrow">LINK UNLOCK FLOW</span><h3>Link step ad scripts</h3><p>Manage both 300 × 250 creatives independently for every unlock step.</p></div></div><form id="ads-scripts-form" class="form step-config-form">${data.steps.map(step=>`<article class="step-setting"><div class="step-config-title"><span class="step-config-number">${step.position}</span><div><h4>Step ${step.position}</h4><small>Two independent scripts for this link step</small></div></div><div class="field ad-script-field"><div class="ad-script-label-row"><label>Ad script 1 · Step ${step.position}</label>${adsScriptToggle(`script-one-enabled-${step.position}`,step.scriptOneEnabled,`Link step ${step.position} ad script 1`)}</div><textarea name="script-one-${step.position}" rows="7" maxlength="50000" spellcheck="false" placeholder="Paste the first HTML or ad network snippet here">${esc(step.scriptOne||'')}</textarea></div><div class="field ad-script-field"><div class="ad-script-label-row"><label>Ad script 2 · Step ${step.position}</label>${adsScriptToggle(`script-two-enabled-${step.position}`,step.scriptTwoEnabled,`Link step ${step.position} ad script 2`)}</div><textarea name="script-two-${step.position}" rows="7" maxlength="50000" spellcheck="false" placeholder="Paste the second HTML or ad network snippet here">${esc(step.scriptTwo||'')}</textarea></div></article>`).join('')}<div class="content-ad-save-row"><span>Each toggle affects only its own script slot.</span><button class="btn btn-primary" type="submit">Save link ads</button></div></form></section>`;
  else if(section==='posts'||section==='trees')content=contentAdScriptFormMarkup(section,section==='posts'?'Posts':'Trees',data.contentScripts?.[section]);
  else content=contentAdScriptFormMarkup('files','Files',data.contentScripts?.files);
  return `<div class="admin-ads-page"><div class="welcome-row admin-ads-heading"><div><h2>Ads scripts</h2><p>Keep each creation type’s ad scripts and controls in its own section.</p></div></div><nav class="admin-ads-tabs" role="tablist" aria-label="Ad script sections">${tabs}</nav><div class="admin-ads-content">${content}</div></div>`;
}

async function adminSettingsPage() {
  const d=await api('/admin/settings');
  return `<div class="welcome-row"><div><h2>General settings</h2><p>Changes apply immediately; rate history is preserved for future calculations.</p></div></div><section class="panel" style="max-width:850px"><form class="form" id="general-settings-form"><div class="field-row"><div class="field"><label>Website name</label><input name="siteName" value="${esc(d.siteName)}" maxlength="80" required /></div><div class="field"><label>Currency</label><input value="${esc(d.currency)}" disabled /></div></div><div class="field-row"><div class="field"><label>User earning rate (cents per 1,000 verified events)</label><input name="earningRatePaisePerThousand" type="number" min="0" value="${Number(d.earningRatePaisePerThousand)}" required /><small>This is a user share rate, not an advertiser revenue figure.</small></div><div class="field"><label>Minimum withdrawal (cents)</label><input name="minimumWithdrawalPaise" type="number" min="1" value="${Number(d.minimumWithdrawalPaise)}" required /></div></div><div class="field"><label>Unlock session expiry (minutes)</label><input name="unlockTtlMinutes" type="number" min="5" max="1440" value="${Number(d.unlockTtlMinutes)}" required /></div><label class="toggle-row"><input type="checkbox" name="unlockEnabled" ${d.unlockEnabled?'checked':''}/> Allow link creation and visitor unlock flows</label><label class="toggle-row"><input type="checkbox" name="referralsEnabled" ${d.referralsEnabled?'checked':''}/> Enable referral registration tracking</label><div class="field"><label>Change reason</label><input name="reason" placeholder="Operational configuration update" maxlength="500" /></div><button class="btn btn-primary">Save settings</button></form><div class="divider"></div><div class="notice warning">Current setup uses local SQLite. For multi-instance production traffic, use a shared database and external rate-limit/session storage before horizontal scaling.</div></section>`;
}

async function adminWithdrawalsPage() {
  const params=new URLSearchParams(location.search),status=params.get('status')||'',q=params.get('q')||'',pageValue=Number(params.get('page')||1),page=Number.isInteger(pageValue)&&pageValue>0?pageValue:1;
  const d=await api(`/admin/withdrawals?status=${encodeURIComponent(status)}&q=${encodeURIComponent(q)}&page=${page}&limit=20`),s=d.summary||{};
  const statuses=['requested','under_review','approved','processing','paid','rejected','cancelled'];
  const reviewButton=x=>`<button class="btn btn-outline btn-small admin-withdrawal-review-button" data-action="withdrawal-review" data-id="${esc(x.id)}" data-status="${esc(x.status)}" data-name="${esc(x.display_name)}" data-email="${esc(x.email)}" data-amount="${Number(x.amount_paise||0)}" data-method="${esc(x.payout_method)}" data-reference="${esc(x.reference||'')}">${icon('shield')} Review request</button>`;
  const rows=d.items.map(x=>`<tr><td>${dateTimeFmt(x.created_at)}</td><td><div class="admin-withdrawal-user"><span class="admin-withdrawal-user-icon">${icon('user')}</span><span><b>${esc(x.display_name)}</b><small>${esc(x.email)}</small></span></div></td><td><b class="admin-withdrawal-amount">${money(x.amount_paise)}</b></td><td><span class="admin-withdrawal-method">${icon(x.payout_method==='Bank transfer'?'bank':x.payout_method==='USDT'?'wallet':'wallet')} ${esc(x.payout_method)}</span></td><td>${statusPill(x.status)}</td><td>${esc(x.reference||'—')}</td><td>${reviewButton(x)}</td></tr>`).join('');
  const cards=d.items.map(x=>`<article class="admin-withdrawal-card"><div class="admin-withdrawal-card-head"><div class="admin-withdrawal-user"><span class="admin-withdrawal-user-icon">${icon('user')}</span><span><b>${esc(x.display_name)}</b><small>${esc(x.email)}</small></span></div>${statusPill(x.status)}</div><div class="admin-withdrawal-card-meta"><span><small>Requested amount</small><b>${money(x.amount_paise)}</b></span><span><small>Payment method</small><b>${esc(x.payout_method)}</b></span><span><small>Submitted</small><b>${dateFmt(x.created_at)}</b></span><span><small>Reference</small><b>${esc(x.reference||'—')}</b></span></div>${reviewButton(x)}</article>`).join('');
  const first=d.total?(d.page-1)*d.pageSize+1:0,last=Math.min(d.page*d.pageSize,d.total);
  const pagination=`<div class="admin-withdrawals-pagination"><span>Showing ${first}–${last} of ${Number(d.total).toLocaleString()} requests</span><div><button type="button" class="btn btn-outline btn-small" data-action="admin-withdrawal-page" data-page="${Math.max(1,d.page-1)}" ${d.page<=1?'disabled':''}>${icon('arrow')} Previous</button><span>Page ${d.page} of ${d.pages}</span><button type="button" class="btn btn-outline btn-small" data-action="admin-withdrawal-page" data-page="${Math.min(d.pages,d.page+1)}" ${d.page>=d.pages?'disabled':''}>Next ${icon('arrow')}</button></div></div>`;
  return `<div class="admin-withdrawals-page"><div class="welcome-row admin-withdrawals-heading"><div><h2>Withdrawals</h2><p>Review payout details, leave a clear note, and track each payment to completion.</p></div><span class="admin-withdrawals-total">${Number(s.total||0).toLocaleString()} requests</span></div><section class="admin-withdrawals-summary">${metricCard('Needs review',Number(s.needsReview||0).toLocaleString(),icon('clock'),'Requested or on hold')}${metricCard('Open amount',money(s.openAmount),icon('wallet'),'Reserved or being processed')}${metricCard('Paid out',money(s.paidAmount),icon('check'),'Confirmed payout total')}${metricCard('All requests',Number(s.total||0).toLocaleString(),icon('file'),'Across every status')}</section><section class="panel admin-withdrawals-panel"><form class="admin-withdrawals-toolbar" id="admin-withdrawal-search"><label class="admin-withdrawals-search"><span>${icon('chart')}</span><input name="q" placeholder="Search user, email, method, reference" value="${esc(q)}"/><button class="btn btn-outline btn-small" type="submit">Search</button></label><label class="admin-withdrawals-filter"><span>Status</span><select name="status" class="select-input"><option value="" ${!status?'selected':''}>All statuses</option>${statuses.map(value=>`<option value="${value}" ${status===value?'selected':''}>${value.replaceAll('_',' ')}</option>`).join('')}</select></label></form><div class="admin-withdrawals-table-wrap">${d.items.length?`<div class="table-wrap"><table class="data-table admin-withdrawals-table"><thead><tr><th>Requested</th><th>Account</th><th>Amount</th><th>Method</th><th>Status</th><th>Reference</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="admin-withdrawals-empty">No withdrawal requests match these filters.</div>'}</div><div class="admin-withdrawals-mobile-list">${cards||'<div class="admin-withdrawals-empty">No withdrawal requests match these filters.</div>'}</div>${pagination}</section></div>`;
}

async function openAdminWithdrawalReview(button){
  const id=button.dataset.id,request=button.dataset.request||{};
  try{
    const details=await api(`/admin/withdrawals/${encodeURIComponent(id)}/payout-details`),status=button.dataset.status||request.status||'';
    request.display_name=button.dataset.name||request.display_name;request.email=button.dataset.email||request.email;request.amount_paise=Number(button.dataset.amount??request.amount_paise??0);request.payout_method=button.dataset.method||request.payout_method;request.reference=button.dataset.reference||request.reference;
    const actions=status==='requested'?['approve','hold','reject','cancel']:status==='under_review'?['approve','hold','reject','cancel']:status==='approved'?['processing','paid','hold','reject','cancel']:status==='processing'?['paid','reject']:[];
    const actionLabel={approve:'Approve request',hold:'Hold for review',reject:'Reject request',cancel:'Cancel request',processing:'Mark processing',paid:'Confirm paid'};
    const actionClass={approve:'btn-primary',hold:'btn-outline',reject:'btn-outline',cancel:'btn-danger',processing:'btn-primary',paid:'btn-primary'};
    const buttons=actions.map(action=>`<button type="button" class="btn ${actionClass[action]}" data-action="admin-withdrawal-decision" data-id="${esc(id)}" data-status="${esc(status)}" data-decision="${action}">${actionLabel[action]}</button>`).join('');
    const formattedDetails=String(details.details||'').split(/\s*\|\s*/).map(part=>`<div class="admin-withdrawal-detail-row"><span>${esc(part.split(':')[0]||'Payment detail')}</span><b>${esc(part.includes(':')?part.slice(part.indexOf(':')+1).trim():part)}</b></div>`).join('');
    showModal(`<div class="sheet-handle" aria-hidden="true"></div><div class="admin-withdrawal-review-head"><div><span class="eyebrow">PAYOUT REVIEW</span><h3>${esc(request.display_name||'Withdrawal request')}</h3><p>${esc(request.email||'')} · ${statusPill(status)}</p></div><button type="button" class="icon-btn" data-action="close-modal" aria-label="Close review">×</button></div><div class="admin-withdrawal-amount-card"><small>Requested payout</small><b>${money(request.amount_paise||0)}</b><span>${esc(details.method||request.payout_method||'Payment method')}</span></div><section class="admin-withdrawal-details"><div class="admin-withdrawal-section-title">${icon('wallet')}<h4>Payment details</h4></div>${formattedDetails||`<div class="admin-withdrawal-detail-row"><span>Receiving details</span><b>${esc(details.details||'Not provided')}</b></div>`}</section><section class="admin-withdrawal-details admin-withdrawal-review-form"><div class="admin-withdrawal-section-title">${icon('pencil')}<h4>Review note &amp; decision</h4></div><p>Write the reason or processing note. This is saved to the request and audit log.</p><label>Review note / remark</label><textarea name="reason" minlength="5" maxlength="500" placeholder="Add a clear note for the user and audit history" required></textarea>${status==='processing'||status==='approved'?`<label>Payment reference <span>Required when confirming payout</span></label><input name="reference" maxlength="120" value="${esc(request.reference||'')}" placeholder="Transaction ID or transfer reference"/>`:''}<div class="admin-withdrawal-actions">${buttons||'<p class="admin-withdrawal-locked">This request is final and cannot be changed.</p>'}</div></section>`, 'edit-sheet admin-withdrawal-review-sheet');
  }catch(error){toast(error.message,'error');}
}

