let demoTimer=null;let demoPopupOpen=false;let pageAdsPopupActive=false;let pageAdsPopupContext='';let demoEventId='';let demoAdUrl='';let demoAdTab=null;let demoPosition=0;let demoProgress={seconds:0,complete:false};let demoWasOpened=false;let demoReturnedEarly=false;let demoScriptsActive=false;let demoPreviewOnly=false;
