    let remaining=10;const slot=ad.dataset.slot;const context=ad.dataset.popupContext||'demo';const timerKey=`${context}:${slot}`;const countdown=ad.querySelector('.interstitial-countdown');const close=ad.querySelector('.interstitial-close');countdown.textContent='Close in 10s';
    const timer=setInterval(()=>{if((!demoPopupOpen&&!pageAdsPopupActive)||!ad.isConnected){clearInterval(timer);interstitialTimers.delete(timerKey);return;}remaining=Math.max(0,remaining-1);if(remaining===0){clearInterval(timer);interstitialTimers.delete(timerKey);ad.dataset.timerComplete='true';countdown.hidden=true;close.hidden=false;close.disabled=false;}else countdown.textContent=`Close in ${remaining}s`;},1000);
