async function finishDemoPopup(){if(!demoPopupOpen)return;if(demoTimer){clearInterval(demoTimer);demoTimer=null;}clearInterstitialTimers();demoPopupOpen=false;demoWasOpened=false;demoReturnedEarly=false;demoPreviewOnly=false;demoScriptsActive=false;const backdrop=document.querySelector('.demo-popup-backdrop');backdrop?.classList.add('is-hiding');setTimeout(()=>{backdrop?.remove();unlockDemoBackground();},180);await refreshUnlock();}
