function finishPageBannerAds(){if(!pageAdsPopupActive)return;const context=pageAdsPopupContext;pageAdsPopupActive=false;pageAdsPopupContext='';clearInterstitialTimers();const backdrop=document.querySelector(`.demo-popup-backdrop[data-popup-context="${context}"]`);backdrop?.classList.add('is-hiding');setTimeout(()=>{backdrop?.remove();unlockDemoBackground();},180);}
function closePageAdSlot(button){const ad=button.closest('.interstitial-ad-popup');const context=ad?.dataset.popupContext;if(!pageAdsPopupActive||!ad||ad.dataset.timerComplete!=='true')return;const timerKey=`${context}:${ad.dataset.slot}`;const timer=interstitialTimers.get(timerKey);if(timer)clearInterval(timer);interstitialTimers.delete(timerKey);ad.remove();if(!document.querySelector(`.demo-popup-backdrop[data-popup-context="${context}"] .interstitial-ad-popup`))finishPageBannerAds();}
