window.addEventListener('message',event=>{if(event.data?.type!=='step-ad-size')return;const frame=[...document.querySelectorAll('.demo-ad-frame')].find(item=>item.contentWindow===event.source);if(!frame)return;if(frame.closest('.interstitial-ad-popup')){frame.style.width='300px';frame.style.height='250px';return;}const maxWidth=Math.max(180,Math.min(window.innerWidth-20,960));const maxHeight=Math.max(120,Math.min(window.innerHeight-40,700));frame.style.width=`${Math.max(150,Math.min(Number(event.data.width)||300,maxWidth))}px`;frame.style.height=`${Math.max(100,Math.min(Number(event.data.height)||250,maxHeight))}px`;});

function sendCreationView(){const tracker=creationViewTracker;if(!tracker)return;const activeSeconds=Math.min(14400,Math.max(0,Math.floor((Date.now()-tracker.startedAt)/1000)));const body=JSON.stringify({viewId:tracker.viewId,activeSeconds});fetch(`/api/v1/public/${tracker.type}/${encodeURIComponent(tracker.slug)}/view`,{method:'POST',headers:{'Content-Type':'application/json'},body,keepalive:true}).catch(()=>{});}
function startCreationViewTracking(type,slug){creationViewTracker={type,slug,viewId:(globalThis.crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})),startedAt:Date.now()};sendCreationView();const tracker=creationViewTracker;tracker.timer=setInterval(()=>{if(creationViewTracker===tracker)sendCreationView();},10000);}
window.addEventListener('pagehide',sendCreationView);
window.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')sendCreationView();});

async function renderRoute() {
  document.querySelector('.analytics-date-filter[open]')?.removeAttribute('open');
  if(overviewTrafficChartInstance){overviewTrafficChartInstance.destroy();overviewTrafficChartInstance=null;}
  if(demoTimer){clearInterval(demoTimer);demoTimer=null;}
  if(demoPopupOpen){demoPopupOpen=false;clearInterstitialTimers();document.querySelector('.demo-popup-backdrop')?.remove();unlockDemoBackground();}
  if(pageAdsPopupActive){const context=pageAdsPopupContext;pageAdsPopupActive=false;pageAdsPopupContext='';clearInterstitialTimers();document.querySelector(`.demo-popup-backdrop[data-popup-context="${context}"]`)?.remove();unlockDemoBackground();}
  if(state.unlockTimer){clearInterval(state.unlockTimer);state.unlockTimer=null;}
  if(creationViewTracker){clearInterval(creationViewTracker.timer);sendCreationView();creationViewTracker=null;}
  const pathname=location.pathname;
  const blogPath=pathname.match(/^\/blog\/([a-z0-9-]{3,80})\/?$/i);
  if(blogPath){app.innerHTML=`<div class="boot"><span class="spinner"></span><span>Loading blog…</span></div>`;app.innerHTML=await publicBlogPage(decodeURIComponent(blogPath[1]));return;}
  const short=pathname.match(/^\/s\/([^/]+)\/?$/);
  if(short){app.innerHTML=`<div class="boot"><span class="spinner"></span><span>Preparing your secure unlock…</span></div>`;return openUnlock(decodeURIComponent(short[1]));}
  const postPath=pathname.match(/^\/post\/([a-z0-9-]{3,80})\/?$/i);
  if(postPath){const slug=decodeURIComponent(postPath[1]);app.innerHTML=`<div class='boot'>Loading article…</div>`;const page=await publicPostPage(slug);app.innerHTML=page.markup;if(document.querySelector('#post-unlock-form'))bindPublicPostLock();else if(page.article){startCreationViewTracking('posts',slug);showPageBannerAds(page.article,'post');}return;}
  const treePath=pathname.match(/^\/tree\/([a-z0-9-]{3,40})\/?$/i);
  if(treePath){const slug=decodeURIComponent(treePath[1]);app.innerHTML=`<div class="boot"><span class="spinner"></span><span>Loading link tree…</span></div>`;const page=await publicTreePage(slug);app.innerHTML=page.markup;if(document.querySelector('#tree-unlock-form'))bindPublicTreeLock();else if(page.tree){startCreationViewTracking('trees',slug);showPageBannerAds(page.tree,'tree');}return;}
  let route=(location.hash||'').slice(1).split('?')[0];
  if(!route && pathname!=='/')route=pathname.replace(/^\//,'').replace(/\/$/,'');
  if(!route) route=state.user?(state.user.role==='admin'||state.user.role==='super_admin'?'admin':'app'):'home';
  state.route=route;
  if(['login','register','forgot','reset','verify'].includes(route)){
    app.innerHTML=authPage(route);bindAuth();return;
  }
  if(route==='blogs'&&!state.user){try{app.innerHTML=await publicBlogsPage();}catch(error){app.innerHTML=`${siteNav()}<main class="public-blog-article-wrap"><div class="notice error">${esc(error.message)}</div></main>${footer()}`;}return;}
  if(route==='notifications'||[...userMenu.map(x=>x[0]),...adminMenu.map(x=>x[0])].includes(route)){
    const result=await renderAuthenticated(route);
    if(result!==null){app.innerHTML=result;if(['login','register','forgot','reset','verify'].includes(route))bindAuth();}
    return;
  }
  if(route==='home') {app.innerHTML=homePage();bindPublic();return;}
  if(publicPages[route]) {app.innerHTML=publicInfoPage(route);return;}
  app.innerHTML=homePage();
}

function initHeroTypewriter(){
  const root=document.querySelector('.hero-typewriter');
  const text=root?.querySelector('.hero-typewriter-text');
  if(!root||!text)return;
  const phrases=(root.dataset.phrases||'clear stats|earning insights|privacy controls|visitor clarity').split('|').filter(Boolean);
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){text.textContent=phrases[0]||'clear stats';return;}
  let phraseIndex=0,visible=(phrases[0]||'clear stats').length,deleting=false,timer;
  const tick=()=>{
    if(!root.isConnected)return;
    const phrase=phrases[phraseIndex]||'clear stats';
    if(deleting){visible=Math.max(0,visible-1);text.textContent=phrase.slice(0,visible);if(visible===0){deleting=false;phraseIndex=(phraseIndex+1)%phrases.length;timer=setTimeout(tick,260);return;}timer=setTimeout(tick,42);return;}
    visible=Math.min(phrase.length,visible+1);text.textContent=phrase.slice(0,visible);
    if(visible===phrase.length){deleting=true;timer=setTimeout(tick,1700);return;}
    timer=setTimeout(tick,78);
  };
  timer=setTimeout(()=>{if(root.isConnected){deleting=true;tick();}},1900);
}
function bindPublic() {
  initHeroTypewriter();
  document.querySelector('#home-short-form')?.addEventListener('submit',e=>{
    e.preventDefault();const value=new FormData(e.currentTarget).get('destinationUrl');
    try{const url=new URL(value);if(!['http:','https:'].includes(url.protocol))throw new Error();}catch{toast('Enter a valid HTTP or HTTPS URL.','error');return;}
    localStorage.setItem('pendingUrl',value);
    if(state.user)navigate('create');else navigate('register');
  });
}

